  str_guide_pop_title_mainskill2 = "Habilidade Conversora",
  str_guide_pop_desc_mainskill2 = "A habilidade conversora é capaz de <color=#ff8f3d>converter certas casas</color> e mudar o <color=#ff8f3d>Tabuleiro de Alquimia</color>. Ao converter casas, você terá mais <color=#ff8f3d>possibilidades de sequências</color>, tornando essa a habilidade mais poderosa de suporte. Use conversões na hora certa para virar o jogo!",
  str_guide_pop_extra_mainskill2 = "A única coisa que nunca muda é a própria mudança.\n                                      —Mensagem de Reinhardt IV—",
