  str_guide_pop_extra_jiguan = "Havia muita tralha nos dias antigos, mas também havia muitas... coisas interessantes! Não é mesmo?\n                                      —Diário de Observação de Gronru—",
  str_guide_pop_title_muchaoguai = "Monstro de Bando",
