  str_guide_pop_extra_muchaoguai = "Alguns Eclipsitas são bem nojentos. Quando dissecados, soltam uma gosma... (Dados Excluídos)\n                                      —Diário de Observação de Gronru—",
  str_guide_pop_title_shenyuan = "Casa Abismal",
