  str_guide_pop_extra_moredamge = "Quanto maior o inimigo, mais fácil é lidar com ele. Apenas feche os olhos e comece a bater.\n                                      —Citações de Barton (não publicado)—",
  str_guide_pop_title_leveltask = "Missão de Estágio",
