  str_guide_warn_11500301 = "Esta é a contagem regressiva até o show. 13 dias restantes! Você tem seu trabalho cortado para você.",
  str_guide_warn_11500302 = "Mas devemos ganhar 150.000 fãs antes de podermos fazer um show.",
  str_guide_warn_11500303 = "Ser um ídolo significa muito treinamento. Existem três modos de treinamento disponíveis. Certifique-se de ficar calmo quando os paparazzi aparecerem!",
