  str_guide_warn_11500305 = "A realização de eventos pode nos ajudar a ganhar mais fãs para que possamos atingir o requisito para o show!",
  str_guide_warn_11500306 = "Aqui está a lista de tarefas desta semana, você pode usá-la como referência para agendamento. Converse com as pessoas durante o treinamento e talvez você consiga algo com isso.",
  str_guide_warn_11500307 = "O restante das informações está no Manual do Produtor. Consulte-o sempre que precisar de algo!",
  str_guide_warn_11500402 = "Vá para o Lair para iniciar o desafio. Além de Lumamber, os jogadores também ganharão Talent Mastery EXP para aumentar seus níveis de talento e ganhar pontos de talento Mastery para se tornarem mais poderosos.",
  str_guide_warn_11500403 = "É aqui que você pode encontrar as missões Lair Reward. Completar missões também lhe renderá Pontos de Maestria de Talentos.",
  str_guide_warn_11500404 = "Gaste Pontos de Maestria de Talentos para desbloquear Habilidades de Maestria de Talentos, Equipamento Caelestite Especial e Relíquias para facilitar os Desafios do Covil!",
  str_guide_warn_11500405 = "Todos os dias, diferentes Aurorianos de teste estarão disponíveis para uso nos Desafios do Covil.",
  str_guide_warn_11500406 = "Você pode encontrar mais informações sobre o Lair aqui. Sinta-se à vontade para navegar a qualquer momento.",
  str_guide_warn_11500601 = "Ganhe EXP de Maestria de Talento suficiente para aumentar seu Nível de Talento e ganhar Pontos de Maestria de Talento.",
  str_guide_warn_11500602 = "Gaste Pontos de Maestria de Talentos para ativar Maestrias de Talentos, como Equipamento Caelestite Especial, para impulsionar sua equipe.",
  str_guide_warn_11500603 = "Depois de gastar Pontos de Maestria de Talentos suficientes, relíquias poderosas podem aparecer aleatoriamente durante os Desafios do Covil.",
  str_guide_warn_11500604 = "Você pode equipar Special Caelestite Gear aqui. Eles fornecem habilidades poderosas adicionais durante o desafio.",
  str_guide_warn_11500605 = "Se quiser editar suas maestrias de talento, você pode redefinir as maestrias de talento ativadas e os pontos de maestria de talento gastos sem nenhum custo.",
  str_guide_warn_11500701 = "Toque aqui para ver os aurorianos em sua equipe.",
  str_guide_warn_11600101 = "O evento Etched Upon the Ocean começou! Junte-se a um elenco de novos amigos de Longzhou enquanto procuramos tesouros perdidos e descobrimos segredos misteriosos em The Homecoming!",
  str_guide_warn_11600102 = "Em Lost Ship At Sea enfrentaremos uma série de difíceis desafios.",
