  str_guide_warn_11600108 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  str_guide_warn_11700101 = "O evento Voto Fragmentário começou! Embarque em uma aventura com seus novos amigos da Courier Union na Mooncrown Pilgrimage.",
  str_guide_warn_11700102 = "Em Feather Seal Crisis, enfrentaremos uma série de desafios difíceis.",
  str_guide_warn_11700103 = "Penas raras obtidas ao concluir as etapas do evento e ao gastar o Prisma podem ser trocadas por várias recompensas no Courier Express.",
  str_guide_warn_11700104 = "Em Sweet Delivery, você pode experimentar a vida trabalhando em um posto Courier Union e resolver a crise sem fim de desejos do Navigator ao mesmo tempo!",
  str_guide_warn_11700105 = "Enfrente os estágios da história do evento e complete as missões em seu Livro de Eventos Especiais!",
  str_guide_warn_11700106 = "Lembre-se de entrar no jogo todos os dias para receber as recompensas diárias.",
  str_guide_warn_11700107 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  str_guide_warn_11700201 = "Estas são as informações do seu pedido atualmente recebido. Toque em um avatar para alternar ordens.",
  str_guide_warn_11700202 = "Vamos terminar o pedido da Lilica primeiro. Ela precisa de roupas, pão e vinho.",
  str_guide_warn_11700203 = "À direita, você pode encontrar a lista completa de mercadorias.",
  str_guide_warn_11700204 = "Vamos colocar um pouco de pão no pacote!",
  str_guide_warn_11700205 = "Ao tocar e segurar para arrastar as mercadorias, você também pode tocar nos botões para girar (tecla R) e virar (tecla T).",
  str_guide_warn_117002051 = "Ao tocar e segurar para arrastar as mercadorias, você também pode tocar nos botões para girar e virar.",
  str_guide_warn_11700206 = "Depois que todos os itens do pedido forem colocados no pacote, lembre-se de tocar no botão de embalagem para enviá-lo. Se nem todos os itens forem colocados no pacote, o andamento da conclusão do pedido final será afetado.",
  str_guide_warn_11700207 = "Toque aqui para pausar a embalagem.",
  str_guide_warn_11700208 = "Agora que você sabe tudo sobre o processo de fluxo de trabalho, vamos continuar empacotando!",
  str_guide_warn_11800101 = "O evento Confess Before the Gavel Strikes começou! Embarque em uma aventura com todos no Hall of Justice durante Heartfelt Admissions.",
  str_guide_warn_11800102 = "Em When the Flowers Wither, enfrentaremos uma série de difíceis desafios.",
  str_guide_warn_11800103 = "Os fragmentos de gesso obtidos ao concluir as etapas do evento e ao gastar o Prisma podem ser usados para resgatar várias recompensas da coleção de evidências.",
  str_guide_warn_11800104 = "Durante o evento Love on Trial, você atuará como juiz assistente, ouvindo os casos em questão e investigando a verdade com os membros da Divisão Romance.",
  str_guide_warn_11800105 = "Enfrente os estágios da história do evento e complete as missões em seu Livro de Eventos Especiais!",
  str_guide_warn_11800106 = "Lembre-se de entrar no jogo todos os dias para receber as recompensas diárias.",
  str_guide_warn_11800107 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  str_guide_warn_11800201 = "Nem todo mundo consegue trabalhar no Tribunal de Justiça. Eu definitivamente aproveitaria ao máximo esta oportunidade se eu fosse você! Toque aqui para ir ao Tribunal de Justiça e ver quais casos estão esperando por você.",
  str_guide_warn_11800202 = "Os casos podem ter finais diferentes, dependendo de como o julgamento for. Se você ficar preso durante a investigação, você pode ir para Case Record e escolher um ponto de seleção de história correspondente para tomar decisões diferentes.",
  str_guide_warn_11800203 = "Você definitivamente será recompensado por seu trabalho duro. Conclua histórias para desbloquear finais e atender a várias condições para reivindicar insígnias e recompensas aqui!",
  str_guide_warn_11800204 = "Anotei todos os detalhes aqui. Lembre-se de lê-los novamente se houver algo que você ainda não entendeu.",
  str_guide_warn_11800301 = "Uau! Você já aprendeu a coletar evidências tão rapidamente? Todas essas evidências serão usadas quando chegar a hora de apresentar as evidências.",
  str_guide_warn_11800401 = "Isso mesmo. É hora de apresentar as evidências! As evidências que você coletou serão listadas na lista de evidências. Não se esqueça de tocá-los para ver informações mais detalhadas.",
  str_guide_warn_11800402 = "Apresentar provas erradas pode afetar sua Competência e o resultado do julgamento!\nVamos tentar selecionar a evidência correta de acordo com a pergunta de Angel. Toque aqui para contra-atacar!",
  str_guide_warn_11800501 = "O Caderno do Juiz é um símbolo da identidade de um juiz. Você está curioso sobre o seu conteúdo?",
  str_guide_warn_11800502 = "Oh! As evidências e os detalhes que você coleta são registrados aqui. Isso torna realmente conveniente verificar tudo.",
  str_guide_warn_11800503 = "Também é muito importante promover um relacionamento mais forte com seus colegas, pois o relacionamento entre você e seus colegas também pode afetar a direção do julgamento. Boa sorte!",
  str_guide_warn_11800601 = "Deixe-me apresentar as regras básicas do jogo! Você precisa controlar seu personagem, lutando por todos os estágios até chegar ao chefe final - Gronkenstein Ruu!",
  str_guide_warn_11800602 = "Você pode tocar neste botão para trocar de personagem, mas eles são exatamente iguais em termos de jogabilidade real - não julgue isso!",
  str_guide_warn_11800603 = "Se houver algo que você ainda não entende, você pode verificar a documentação aqui.",
  str_guide_warn_11800701 = "Os estágios serão desbloqueados gradualmente ao longo do tempo. Vamos tentar a primeira fase!",
  str_guide_warn_11800702 = "Contanto que você complete o primeiro alvo de cada estágio, você o limpará! Você também pode ir para todos os alvos, se quiser!",
  str_guide_warn_11800703 = "Vamos nos preparar para fazer barulho!",
  str_guide_warn_11800801 = "É isso! Você precisa manter seu personagem avançando e tentar não deixar os Eclipsites te pegarem! Faça-o para o alvo!",
  str_guide_warn_11800802 = "Há um Eclipsite normal à frente! Aproveite o momento perfeito para pular de cabeça para baixo, então será o fim do jogo para aquele novato normie!",
  str_guide_warn_11800803 = "Agora! Toque no botão Ir!",
  str_guide_warn_118008031 = "Agora! Toque no botão Ir (T)!",
  str_guide_warn_11800804 = "Nada mal! Você é um jogador nato!",
  str_guide_warn_11800805 = "Em seguida, teremos que lidar com um Eclipsite voador. Depois de pular, você pode atacar um Eclipsite em uma posição mais alta usando um salto duplo!",
  str_guide_warn_11800806 = "Agora, toque em Saltar!",
  str_guide_warn_11800807 = "Toque em Pular novamente para usar seu ataque de salto duplo!",
  str_guide_warn_11800808 = "Agora você já domina oficialmente os controles básicos do jogo! Tente limpar esta fase sozinho!",
  str_guide_warn_11800901 = "Navegador, um passarinho me disse que você tem reclamado que a primeira fase é muito fácil para você!",
  str_guide_warn_11800902 = "Bem, não se preocupe, tenho novos monstros ainda mais difíceis esperando por você! Esses Eclipsites com cabeça de capacete precisam ser saltados duas vezes antes que você possa contá-los!",
