  ["str_guide_circle_N3_1-5_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N3_1-5_Rb"] = "Use obstáculos a seu favor ao tentar evitar ataques do Bispo Eclipse.",
  ["str_guide_circle_N3_1-7_LtT"] = "Rainha Ardilosa",
  ["str_guide_circle_N3_1-7_Lt"] = "Ataca de acordo com as regras do movimento da rainha no xadrez, causando um alto dano em alvos ao alcance. Se os alvos estão fora de alcance, ela espera pacientemente pela oportunidade de atacar.",
  ["str_guide_circle_N3_1-7_RtT"] = "Dicas Importantes",
  ["str_guide_circle_N3_1-7_Rt"] = "Cuidado para não ficar dentro do alcance de aviso prévio da Rainha Ardilosa, senão você pode esperar uma grande quantidade de dano.",
  ["str_guide_circle_N3_1-9_LtT"] = "Peão Perdido",
  ["str_guide_circle_N3_1-9_Lt"] = "Move para frente a cada rodada, atacando em saltos. Ao chegar na margem inferior esquerda do tabuleiro, é promovido para outra peça na ordem seguinte: Torre, Cavalo, Bispo, Rainha.",
  ["str_guide_circle_N3_1-9_RtT"] = "Tática de Abordagem",
  ["str_guide_circle_N3_1-9_Rt"] = "Evite os ataques de CHAMP do Peão Perdido e derrote-o antes de ser promovido.",
  ["str_guide_circle_N3_1-20_LbT"] = "Monarca Desolado",
  ["str_guide_circle_N3_1-20_Lb"] = "Controlador dos monstros de xadrez. Um mestre estrategista que se destaca em comandar tropas e forçar o oponente a cair em suas armadilhas.",
  ["str_guide_circle_N3_1-20_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N3_1-20_Rb"] = "Ele força o tabuleiro a se mover para baixo uma casa por rodada, acelerando a transformação de seus Peões Perdidos. Elimine todos os Peões Perdidos o mais rápido possível e preste atenção na posição de cada peça a cada rodada.",
  ["str_guide_circle_N5_1-3_LtT"] = "Abismo",
  ["str_guide_circle_N5_1-3_Lt"] = "Após um certo número de rodadas, ele libera sua energia interna para se auto destruir, danificando o terreno.",
  ["str_guide_circle_N5_1-3_RtT"] = "Casas Danificadas",
  ["str_guide_circle_N5_1-3_Rt"] = "Casas quebradas não podem ser usadas por Aurorians.",
  ["str_guide_circle_N5_1-3_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N5_1-3_Rb"] = "Derrote o Abismo antes que ele exploda!",
  ["str_guide_circle_N5_1-10_LbT"] = "Hylingerr",
  ["str_guide_circle_N5_1-10_Lb"] = "Um monstro gigante, tão astuto quanto é poderoso. Causa dano alto a alvos em alcance e possui a habilidade de registrar posições dos alvos.",
  ["str_guide_circle_N5_1-10_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N5_1-10_Rb"] = "Esse monstro é relativamente grande. Preste atenção a seu posicionamento para evitar o dano que ele causa.",
  ["str_guide_circle_N6_1-10_LtT"] = "Mirren Gautier",
  ["str_guide_circle_N6_1-10_Lt"] = "Um nobre caído, seu poder cresce conforme seu ódio por Lumópolis se aprofunda...",
  ["str_guide_circle_N6_1-10_RtT"] = "Esconder",
  ["str_guide_circle_N6_1-10_Rt"] = "Pode se esconder em casas quebradas, ficando imune ao dano de ataques normais e direcionais.",
  ["str_guide_circle_N6_1-10_LbT"] = "Rancor",
  ["str_guide_circle_N6_1-10_Lb"] = "Pode teletransportar várias vezes e quebrar casas no campo de batalha se o inimigo não estiver no alcance de ataque.",
  ["str_guide_circle_N6_1-10_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N6_1-10_Rb"] = "Elimine casas quebradas antes de atacar!",
  ["str_guide_circle_N6_1-1_LtT"] = "Mantleworm",
  ["str_guide_circle_N6_1-1_Lt"] = "Um Eclipsita que já morou nas profundezas do Território Secreto e se destaca no uso de ataques subterrâneos. Também é dito que é capaz de cavar passagens subterrâneas para outros Eclipsitas.",
  ["str_guide_circle_N6_1-1_RtT"] = "Nota",
  ["str_guide_circle_N6_1-1_Rt"] = "Destaca-se na utilização de terreno destruído. É capaz de causar muito dano às unidades em torno das Casas Destruídas.",
  ["str_guide_circle_N6_1-1_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N6_1-1_Rb"] = "Controle o número de casas quebradas no campo de batalha e preste atenção na posição dos ataques!",
  ["str_guide_circle_N7_1-10_LtT"] = "Maude Solus",
  ["str_guide_circle_N7_1-10_Lt"] = "Passa por uma perigosa transformação temporária sem pensar duas vezes para ganhar um novo poder.",
  ["str_guide_circle_N7_1-10_RtT"] = "Fantoche Solus",
  ["str_guide_circle_N7_1-10_Rt"] = "Pode invocar Eclipsitas constantemente para ajudar na batalha.",
  ["str_guide_circle_N7_1-10_LbT"] = "Tática de Abordagem",
  ["str_guide_circle_N7_1-10_Lb"] = "Evite que Maude invoque Eclipsitas e ataque-o diretamente!",
  ["str_guide_circle_N7_1-4_LbT"] = "Preste atenção!",
  ["str_guide_circle_N7_1-4_Lb"] = "Os Eclipsitas que se transformaram após receberem fortificantes parecem completamente diferentes daqueles que estamos acostumados! Cuidado!",
  ["str_guide_circle_N9_1-3_LbT"] = "???",
  ["str_guide_circle_N9_1-3_Lb"] = "Eclipsita Enigmático de origem desconhecida. Sua presença não parece se adequar à realidade que conhecemos.",
  ["str_guide_circle_N9_1-3_RbT"] = "Dons do Monstro",
  ["str_guide_circle_N9_1-3_Rb"] = "Quando não estiver na Hora da Aurora, ganha redução de dano considerável.",
  ["str_guide_circle_N9_1-3_LtT"] = "Tática de Abordagem",
  ["str_guide_circle_N9_1-3_Lt"] = "Ataque o monstro durante a Hora da Aurora!",
  ["str_guide_circle_N9_1-10_LbT"] = "Aterrorizador",
  ["str_guide_circle_N9_1-10_Lb"] = "A poeira abaixou e a identidade de um conhecido inimigo alienígena ainda vai ser revelada. É hora de mostrar sua decisão.",
  ["str_guide_circle_N9_1-10_RbT"] = "Dons do Monstro",
  ["str_guide_circle_N9_1-10_Rb"] = "Quando não estiver na Hora da Aurora, ganha redução de dano considerável. Capaz de invocar lacaios para ajudar na batalha.",
  ["str_guide_circle_N9_1-10_LtT"] = "Tática de Abordagem",
  ["str_guide_circle_N9_1-10_Lt"] = "Elimine os lacaios e ataque o Aterrorizador, o máximo que puder, durante a Hora da Aurora!",
  ["str_guide_circle_N11_1-3_LtT"] = "Jammer I",
  ["str_guide_circle_N11_1-3_Lt"] = "Uma armadilha misteriosa da Cidade Perdida. Parece ser um protótipo do Jammer inicial.",
  ["str_guide_circle_N11_1-3_RtT"] = "Características da armadilha",
  ["str_guide_circle_N11_1-3_Rt"] = "Com sua capacidade de perturbar a área ao redor, os Aurorianos recebem dano ao se mover ao redor.",
  ["str_guide_circle_N11_1-3_LbT"] = "Tática de Abordagem",
  ["str_guide_circle_N11_1-3_Lb"] = "Cuidado para não se aproximar do Jammer ao se mover!",
  ["str_guide_circle_N11_1-12_LbT"] = "Valência",
  ["str_guide_circle_N11_1-12_Lb"] = "As identidades dos moradores da Cidade Perdida permanecem um mistério.",
  ["str_guide_circle_N11_1-12_RbT"] = "Cuidado!",
  ["str_guide_circle_N11_1-12_Rb"] = "Valencia é capaz de convocar e controlar armadilhas poderosas para ajudá-la na batalha. Cuidado com as armadilhas dela por aí!",
  ["str_guide_circle_N12_1-1_LbT"] = "Kittypus",
  ["str_guide_circle_N12_1-1_Lb"] = "Um companheiro especial de Gretel. Assemelha-se a um gato com muitas pernas... É fofo, mas de alguma forma perturbador.",
  ["str_guide_circle_N12_1-1_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N12_1-1_Rb"] = "Tentaclaw pode transferir o dano sofrido para o corpo principal. Este recurso pode ser usado para combater monstros.",
  ["str_guide_circle_N12_1-2_LbT"] = "Ironstomp",
  ["str_guide_circle_N12_1-2_Lb"] = "Um companheiro especial de Gretel. Tem um par de pernas extremamente fortes que podem repelir qualquer inimigo.",
  ["str_guide_circle_N12_1-2_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N12_1-2_Rb"] = "Ironstomp é um triturador de ladrilhos habilidoso. Traga Aurorianos conversores de peças para combatê-lo.",
  ["str_guide_circle_N12_1-3_LbT"] = "Basilisco",
  ["str_guide_circle_N12_1-3_Lb"] = "Um companheiro especial de Gretel. Brincalhão e enérgico, gosta particularmente de lutar contra um grupo de inimigos.",
  ["str_guide_circle_N12_1-3_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N12_1-3_Rb"] = "Por trás da pele áspera de Basilisco há um coração terno. Habilidades de controle provavelmente funcionam bem.",
  ["str_guide_circle_N12_1-4_LbT"] = "porco-espinho",
  ["str_guide_circle_N12_1-4_Lb"] = "Um companheiro especial de Gretel. Geralmente quieto e plácido, mas conhecido por enlouquecer em batalha. Aproxime-se com cautela.",
  ["str_guide_circle_N12_1-4_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N12_1-4_Rb"] = "Spikeyhog está coberto de espinhos. Melhor para os aurorianos manterem distância.",
  ["str_guide_circle_N13_1-1_LbT"] = "Espada do Submundo",
  ["str_guide_circle_N13_1-1_Lb"] = "Ex-chefe do Wisp que se dedica a combater os invasores da Ilha das Nuvens.",
  ["str_guide_circle_N13_1-1_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N13_1-1_Rb"] = "Sword of the Underworld fará escolhas táticas diferentes com base em sua distância dos Aurorianos. Permaneça a uma distância dela para ganhar capacidade de recuperação e lidar melhor com seus ataques.",
  ["str_guide_circle_N14_1-1_LbT"] = "Nagi - Lâmina da Fúria",
  ["str_guide_circle_N14_1-1_Lb"] = "A frenética Nagi atacará qualquer um que ela perceba como um intruso.",
  ["str_guide_circle_N14_1-1_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N14_1-1_Rb"] = "Observe a sequência de ataque de Nagi - Fury Blade para evitar Lethal Damage e Contra-ataque quando surgir a oportunidade.",
  ["str_guide_circle_N13_1-12_LbT"] = "Fujikumo Nobutora",
  ["str_guide_circle_N13_1-12_Lb"] = "Um tirano que veio de outra ilha do Extremo Oriente para governar a Ilha das Nuvens, e ele fará qualquer coisa para declarar soberania sobre ela.",
  ["str_guide_circle_N13_1-12_RbT"] = "Cuidado!",
  ["str_guide_circle_N13_1-12_Rb"] = "Fujikumo Nobutora pode convocar um grande número de fantasmas para ajudá-lo na batalha.",
  ["str_guide_circle_N13_1-12_LtT"] = "Tática de Abordagem",
  ["str_guide_circle_N13_1-12_Lt"] = "Limpe os fantasmas no campo de batalha a tempo.",
  ["str_guide_circle_N14_1-12_LbT"] = "Fujikumo Nobutora - Devorar",
  ["str_guide_circle_N14_1-12_Lb"] = "Devido à sua obsessão, ele se transformou em um homem hediondo e prometeu eliminar todos os que resistissem.",
  ["str_guide_circle_N14_1-12_RbT"] = "Aviso!",
  ["str_guide_circle_N14_1-12_Rb"] = "Fujikumo Nobutora - Devour lançará diferentes habilidades com base na posição dos Aurorianos.",
  ["str_guide_circle_N14_1-12_LtT"] = "Tática de Abordagem",
  ["str_guide_circle_N14_1-12_Lt"] = "Quando estiver em batalha, lembre-se de se posicionar com cuidado e contra-atacar adequadamente.",
  ["str_guide_circle_N13_1-2_LbT"] = "Fantasma",
  ["str_guide_circle_N13_1-2_Lb"] = "Um monstro especial do Extremo Oriente que dizem ser \"nem vivo nem morto\" e é extremamente hostil com os vivos.",
  ["str_guide_circle_N13_1-2_RbT"] = "Dons do Monstro",
  ["str_guide_circle_N13_1-2_Rb"] = "Suas habilidades de luta podem não ser assustadoras, mas seus números são.",
  str_guide_fail_1 = "Evolua Aurorians",
  str_guide_fail_2 = "Subir o nível e ascender Aurorians são maneiras de aumentar consideravelmente suas habilidades.",
  str_guide_fail_3 = "Aurorians que podem ser melhorados:",
  str_guide_fail_4 = "Obtenção de Materiais de Evolução",
  str_guide_fail_5 = "Obtenha materiais de EXP de Aurorians e materiais de Avanço das seguintes maneiras",
  str_guide_fail_6 = "Obtido de: Estágios de Recurso de Neve Esquecida e Estágios Principais",
  str_guide_fail_7 = "Toque para pular",
  str_guide_warn_level_speed = "AVISO: É preciso subir o nível!",
  str_guide_fail_8 = "Estágio falhou",
  str_guide_warn_40096 = "Toque aqui",
  str_guide_fail_9 = "Familiarize-se com as habilidades de cada peça",
  str_guide_fail_10 = "Conheça as características de cada peça e extraia todo o seu potencial.",
  str_guide_fail_11 = "Ajuste as estratégias de combate",
  str_guide_fail_12 = "Cada inimigo segue um padrão de movimento fixo. Ajuste sua estratégia de combate de acordo.",
  ["str_guide_circle_N17_1-14_LtT"] = "Claudia",
  ["str_guide_circle_N17_1-14_Lt"] = "A IA na base subterrânea de Eraveil que guarda a base há milhares de anos e é responsável por limpar todos os inimigos invasores.",
  ["str_guide_circle_N17_1-14_RbT"] = "Dons do Monstro",
  ["str_guide_circle_N17_1-14_Rb"] = "Resiste perfeitamente a ataques normais quando está na plataforma ou acima Asher, imediatamente salta para outra plataforma dentro de 2 clusters no momento em que o que está sob seus pés é esmagado.",
  ["str_guide_circle_N17_1-14_LbT"] = "Tática de Abordagem",
  ["str_guide_circle_N17_1-14_Lb"] = "Use o Sniper para acertar diretamente Claudia, também tome cuidado para não destruir a plataforma.",
  ["str_guide_circle_N17_2-14_LtT"] = "Asher",
  ["str_guide_circle_N17_2-14_Lt"] = "A IA na base subterrânea de Eraveil que parece grande e pesada, é Claudiaamigo do.",
  ["str_guide_circle_N17_2-14_RbT"] = "Dons do Monstro",
  ["str_guide_circle_N17_2-14_Rb"] = "Mostra traços de imortalidade e se levanta logo após ser derrubado, mas a quantidade de HP restaurada diminui a cada derrubada.",
  ["str_guide_circle_N17_2-14_LbT"] = "Tática de Abordagem",
  ["str_guide_circle_N17_2-14_Lb"] = "Contorne este poderoso escudo e derrote Claudia O mais breve possível.",
  ["str_guide_circle_N18_1-12_LtT"] = "Minos",
  ["str_guide_circle_N18_1-12_Lt"] = "O mordomo da medalha de ouro da Andersen que não deixa manchas, lixo ou vermes sem vigilância.",
  ["str_guide_circle_N18_1-12_RtT"] = "Dons do Monstro",
  ["str_guide_circle_N18_1-12_Rt"] = "Minos alternará entre o Estado Mortal e o Estado Minotauro com base em sua pilha de Marcas. Redefine todas as peças que ele passa para peças aprimoradas ou enfraquecidas, dependendo de seu estado.",
  ["str_guide_circle_N18_1-12_RbT"] = "Aviso!",
  ["str_guide_circle_N18_1-12_Rb"] = "A maioria dos ataques de Minos se tornam mais fortes à medida que ele ganha mais stacks de sua marca. Quanto mais pilhas de marcas ele tiver e quanto mais peças aprimoradas no campo, mais perigosos serão seus ataques.",
  ["str_guide_circle_N18_1-1_LtT"] = "Ladrilho Enfraquecido",
  ["str_guide_circle_N18_1-1_Lt"] = "As peças especiais opostas às peças aprimoradas podem reduzir os danos causados pelas conexões do jogador.",
  ["str_guide_circle_N18_1-1_RbT"] = "Características",
  ["str_guide_circle_N18_1-1_Rb"] = "Aurorianos que passarem receberão um debuff de redução de dano de conexão 2 vezes maior que um bloco normal.",
  ["str_guide_circle_N20_1-12_LtT"] = "Guardião do Núcleo",
  ["str_guide_circle_N20_1-12_Lt"] = "Um guardião gigantesco que protege o núcleo de energia da nave. Ele vai acordar e lutar quando o Núcleo estiver sob ameaça.",
  ["str_guide_circle_N20_1-12_LbT"] = "Características do local",
  ["str_guide_circle_N20_1-12_Lb"] = "Quando o Core Guardian estiver acordado, ele irá girar o lado do cubo mágico para longe do jogador no final de cada rodada, alterando a distribuição dos monstros no campo.",
  ["str_guide_circle_N20_1-12_RbT"] = "Fraquezas do Monstro",
  ["str_guide_circle_N20_1-12_Rb"] = "O Módulo Congelar é a fraqueza do Guardião. Derrotar o Freeze Module paralisará o Core Guardian por 1 rodada e tornará mais fácil se machucar.",
  str_guide_warn_5193011 = "Os personagens do P5R Collab entram na batalha com suas habilidades especiais.",
  str_guide_warn_5193012 = "Toque aqui para ver a Descrição da Habilidade.",
  str_guide_warn_5193013 = "Lance a habilidade especial e cuide desses inimigos de uma só vez.",
  ["str_guide_circle_N22_1-10_LtT"] = "Casta",
  ["str_guide_circle_N22_1-10_Lt"] = "Aparentemente distante, mas na verdade muito responsável. Juntou-se a Pollux para formar a dupla de mercenários apelidada de \"Raven's Blood\" para melhor defender as crianças que vivem na igreja.",
  ["str_guide_circle_N22_1-10_RbT"] = "Dons do Monstro",
  ["str_guide_circle_N22_1-10_Rb"] = "Lança diferentes ataques de habilidade de acordo com as posições dos aliados; pode neutralizar habilidades ativas aliadas.",
  ["str_guide_circle_N22_1-10_LbT"] = "Tática de Abordagem",
  ["str_guide_circle_N22_1-10_Lb"] = "Fica de olho nas posições relativas de ambos os lados; controla a frequência de liberação de habilidades ativas.",
  ["str_guide_circle_sailing_1-1_LtT"] = "Wormgate",
  ["str_guide_circle_sailing_1-1_Lt"] = "Embora não esteja claro como funciona, os Eclipsites continuarão a aparecer a partir dele. A batalha provavelmente se tornará muito difícil se não for tratada o mais rápido possível.",
  ["str_guide_circle_sailing_1-1_RbT"] = "Características",
  ["str_guide_circle_sailing_1-1_Rb"] = "Se o Wormgate for aberto, Eclipsites será invocado no início da próxima rodada.",
  ["str_guide_circle_sailing_1-1_RtT"] = "Aviso!",
  ["str_guide_circle_sailing_1-1_Rt"] = "Se um Eclipsite estiver acima do Wormgate no início da rodada, o Wormgate não convocará novos Eclipsites nesta rodada.",
  ["str_guide_circle_sailing_2-1_LtT"] = "Pedra Halo",
  ["str_guide_circle_sailing_2-1_Lt"] = "Rochas com Lumina desconhecida, comumente presentes em ruínas, supostamente alteram a Lumina ao seu redor.",
  ["str_guide_circle_sailing_2-1_RbT"] = "Características",
  ["str_guide_circle_sailing_2-1_Rb"] = "No início de cada rodada do jogador, a Halo Stone converte todas as peças de um elemento diferente dentro de um determinado intervalo no mesmo elemento que ela.",
  ["str_guide_circle_sailing_2-1_RtT"] = "Estratégia",
  ["str_guide_circle_sailing_2-1_Rt"] = "O elemento da Halo Stone sempre será o mesmo que o elemento do ladrilho em que está. Nossos aliados podem usar isso para aproveitar a vantagem na batalha.",
  ["str_guide_circle_sailing_2-2_RbT"] = "Aviso!",
  ["str_guide_circle_sailing_2-2_Rb"] = "Se a peça sob a Halo Stone se tornar uma peça cromática, a Halo Stone será destruída.",
  ["str_guide_circle_sailing_2-3_LtT"] = "Estela de Proibição de Habilidade",
  ["str_guide_circle_sailing_2-3_Lt"] = "Uma pequena estela misteriosa encontrada em certas ruínas. As runas nele impõem certas restrições aos atacantes.",
  ["str_guide_circle_sailing_2-3_RbT"] = "Características",
  ["str_guide_circle_sailing_2-3_Rb"] = "Silencia todos os Aurorianos dentro de um certo alcance, tornando-os incapazes de usar habilidades ativas.",
  ["str_guide_circle_sailing_2-4_LtT"] = "Estratégia",
  ["str_guide_circle_sailing_2-4_Lt"] = "Use uma habilidade de combinação em cadeia ou habilidade ativa que cause dano de área para causar dano a Estelas de Proibição de Habilidade. Eles vão quebrar depois de receber uma certa quantidade de dano.",
  ["str_guide_circle_N22_2-1_LtT"] = "Dons do Monstro",
  ["str_guide_circle_N22_2-1_Lt"] = "Ele pode usar torres para causar dano contínuo ao inimigo e afastar quaisquer inimigos que cheguem muito perto dele. O guarda se fortalecerá quando perceber uma grande ameaça.",
  ["str_guide_circle_N22_2-1_RtT"] = "Tática de Abordagem",
  ["str_guide_circle_N22_2-1_Rt"] = "O Canhão Autopropulsado pode causar dano ao mesmo inimigo várias vezes na mesma rodada, mas não é necessário que o jogador evite todos os acertos, pois não causa muito dano a cada acerto.",
  ["str_guide_circle_N22_2-1_RbT"] = "Canhão Autopropulsado",
  ["str_guide_circle_N22_2-1_Rb"] = "Guardas poderosos capazes de patrulhar por conta própria. Ambos os canhões principais e de ombro são incrivelmente poderosos. Apenas um desses guardas pode causar grandes danos.",
  ["str_guide_circle_N23_1-14_LtT"] = "Astor",
  ["str_guide_circle_N23_1-14_Lt"] = "Um espírito feminino errante, sem mestre nem vontade própria; tudo o que resta é uma poderosa inimizade para com os vivos. Através de rituais sinistros, esse espírito pode ser combinado com Darkflow para criar uma poderosa entidade sobrenatural.",
  ["str_guide_circle_N23_1-14_RtT"] = "Dons do Monstro",
  ["str_guide_circle_N23_1-14_Rt"] = "Atravessa uma área designada e absorve a energia das Velas da Morte para se fortalecer.",
  ["str_guide_circle_N23_1-14_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N23_1-14_Rb"] = "Apague as Velas Mortais para manter distância de Astor.",
  ["str_guide_circle_13-14_LtT"] = "diavola",
  ["str_guide_circle_13-14_Lt"] = "O exterior do corpo da flor é fortemente protegido por folhas duras, mas as habilidades do Sniper podem causar dano letal à flor e expor sua fraqueza.",
  ["str_guide_circle_13-14_RtT"] = "Dons do Monstro",
  ["str_guide_circle_13-14_Rt"] = "Quando desperta, Diavola contra-ataca todos os ataques normais desferidos pelos aurorianos e inflige 1 acúmulo de toxina neles.",
  ["str_guide_circle_13-14_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_13-14_Rb"] = "Priorize atacar as flores de Diavola primeiro para paralisá-la e causar dano a ela com segurança. Lembre-se de cuidar dos Dawn Sprites que ele invoca.",
  ["str_guide_circle_13-7-1_Lt"] = "Um Eclipsita nascido nas condições extremas do fim dos tempos. Tem uma figura distorcida e há muito perdeu a capacidade de pensar com inteligência. Tudo o que resta é o desejo de seguir em frente e devorar tudo em seu caminho.",
  ["str_guide_circle_13-7-1_LtT"] = "Jormungand",
  ["str_guide_circle_13-7-1_Rt"] = "A cabeça de Jormungand é o centro de seus ataques. Ele causa muito dano aos inimigos perto de sua cabeça. Jormungand morre quando sua cabeça tem 0 HP restante.",
  ["str_guide_circle_13-7-1_RtT"] = "Características da cabeça de Jormungand",
  ["str_guide_circle_13-7-1_Rb"] = "Os jogadores devem se lembrar de causar dano à cabeça de Jormungand à distância. Jormungand morrerá imediatamente se sua cabeça for bloqueada por obstáculos por todos os lados.",
  ["str_guide_circle_13-7-1_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_13-7-2_Lt"] = "O corpo de Jormungand se replica ao longo do tempo e cresce a cada rodada. Seu corpo é imune a todos os danos.",
  ["str_guide_circle_13-7-2_LtT"] = "Características do Corpo de Jormungand",
  ["str_guide_circle_13-7-3_Lt"] = "A cauda de Jormungand é seu ponto fraco. Todo o dano causado na cauda será transferido para a cabeça e você causará mais dano.",
  ["str_guide_circle_13-7-3_LtT"] = "Características da Cauda de Jormungand",
  ["str_guide_circle_14-9-1_LtT"] = "espírito da lanterna",
  ["str_guide_circle_14-9-1_Lt"] = "Um Eclipsite que foi modificado por Asmodeus. Seus desejos são controlados por Asmodeus, então ele obedece a todos os seus comandos.",
  ["str_guide_circle_14-9-1_RtT"] = "Características dos Monstros I",
  ["str_guide_circle_14-9-1_Rt"] = "Se um Lantern Spirit pode se teletransportar através de Aurorians ao atacar, ele cria uma corrente que faz com que o dano recebido e o HP recuperado sejam compartilhados entre as partes vinculadas.",
  ["str_guide_circle_14-9-1_RbT"] = "Teletransporte",
  ["str_guide_circle_14-9-1_Rb"] = "O Lantern Spirit pode se teletransportar se puder passar pelo ladrilho em que o auroriano está e se mover para o ladrilho do outro lado.",
  ["str_guide_circle_14-9-2_LtT"] = "Correntes",
  ["str_guide_circle_14-9-2_Lt"] = "Quando uma das partes conectadas pela cadeia sofre dano ou recupera HP, a outra parte receberá a mesma quantidade de dano ou recuperará a mesma quantidade de HP.",
  ["str_guide_circle_14-9-2_RtT"] = "Tática de Abordagem",
  ["str_guide_circle_14-9-2_Rt"] = "Mantenha uma certa distância de um Lantern Spirit para quebrar a corrente.",
  ["str_guide_circle_14-9-2_RbT"] = "Derrote ou atraia-os!",
  ["str_guide_circle_14-9-2_Rb"] = "Derrotar ou atrair o Espírito da Lanterna em sua direção também é uma maneira de se libertar da corrente que o conecta.",
  ["str_guide_circle_14-14-1_LtT"] = "Asmodeus",
  ["str_guide_circle_14-14-1_Lt"] = "O poderoso Wraith tem a habilidade terrível de ver através de todos os desejos de seus oponentes e gosta de manipulá-los.",
  ["str_guide_circle_14-14-1_RtT"] = "Características dos Eclipsitos",
  ["str_guide_circle_14-14-1_Rt"] = "Asmodeus se divide em dois ao entrar no campo. Um clone é imune a habilidades e o outro é imune a ataques normais. Eles estão conectados pela Cadeia de Desejo.",
  ["str_guide_circle_14-14-1_RbT"] = "cadeia de desejo",
  ["str_guide_circle_14-14-1_Rb"] = "Quando qualquer Asmodeus conectado pela Cadeia de Desejo sofre dano ou recupera PV, o outro Asmodeus passará pelo mesmo efeito. Após Asmodeus tomar uma ação, Regiões Escuras serão geradas sob a Cadeia de Desejo.",
  ["str_guide_circle_14-14-2_LtT"] = "Asmodeus",
  ["str_guide_circle_14-14-2_Lt"] = "Este Asmodeus é imune a dano de ataque normal e tem poderosos ataques à distância.",
  ["str_guide_circle_14-14-3_RtT"] = "Asmodeus",
  ["str_guide_circle_14-14-3_Rt"] = "Este Asmodeus é imune a dano de habilidade e se liga aos aurorianos que atinge com sua Corrente de Pesadelos.",
  ["str_guide_circle_14-14-3_RbT"] = "cadeia de pesadelos",
  ["str_guide_circle_14-14-3_Rb"] = "Aurorianos conectados pela Cadeia de Pesadelos sofrerão dano para cada ladrilho que atravessarem. Deixar o alcance efetivo da Chain of Nightmares irá quebrá-la.",
  ["str_guide_circle_14-7_LtT"] = "Cerritus",
  ["str_guide_circle_14-7_Lt"] = "O novo Eclipsite encontrado durante a exploração parece ser uma variante de um poderoso Eclipsite, exceto que é mais perturbado e muito mais destrutivo.",
  ["str_guide_circle_14-7_RtT"] = "Dons do Monstro",
  ["str_guide_circle_14-7_Rt"] = "Cerritus ataca os aurorianos batendo neles e tem a poderosa habilidade de invocar seixos e mudar o terreno. Cerritus fica mais forte conforme a batalha avança. Ataques que não matam Cerritus apenas o tornam mais forte! A cada poucas rodadas, Cerritus ruge com raiva e entra em um estado de loucura.",
  ["str_guide_circle_14-7_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_14-7_Rb"] = "Preste atenção à sua posição relativa dos inimigos. Use as habilidades no momento certo para terminar as batalhas rapidamente.",
  str_guide_circle_N24_petTry_LtT = "Orbe de Cura",
  str_guide_circle_N24_petTry_Lt = "O objeto invocado de Axelia. Ela se cura quando absorve isso com sua Habilidade Ativa ou quando a equipe passa por ela. Transforma após existir por 2 rodadas, fornece efeitos de cura adicionais.",
  str_guide_circle_N24_petTry_Lt_1 = "O objeto invocado de Axelia. Ela se cura quando absorve isso com sua Habilidade Ativa ou quando a equipe passa por ela.",
  ["str_guide_circle_N25_1-4_LtT"] = "Venodex",
  ["str_guide_circle_N25_1-4_Lt"] = "Diz-se ser um parente distante de uma espécie de Eclipsite capaz de se autodetonar, exceto que esta variedade pode lançar bolas de lodo venenosas, causando danos significativos aos organismos vivos.",
  ["str_guide_circle_N25_1-4_LbT"] = "Dons do Monstro",
  ["str_guide_circle_N25_1-4_Lb"] = "Pulveriza veneno em linha reta ou na localização de um auroriano, infligindo veneno a todos os inimigos e aliados dentro do alcance do veneno.",
  ["str_guide_circle_N25_1-4_RtT"] = "Estratégia",
  ["str_guide_circle_N25_1-4_Rt"] = "Talvez você possa usar seu veneno para fazer outros inimigos sofrerem.",
  ["str_guide_circle_N25_1-16_RtT"] = "Dreamwalker",
  ["str_guide_circle_N25_1-16_Rt"] = "Diz-se ser o Phantom\"irmão\" de Eternal Night. É capaz de usar táticas diferentes de acordo com a hora do dia e é extremamente difícil de lidar.",
  ["str_guide_circle_N25_1-16_LtT"] = "Dons do Monstro",
  ["str_guide_circle_N25_1-16_Lt"] = "Tem a capacidade de atacar aurorianos à distância e pode lançar ataques em tela cheia. Pode convocar fantasmas que cercam os aurorianos, mas não podem atacar.",
  ["str_guide_circle_N25_1-16_LbT"] = "Estratégia",
  ["str_guide_circle_N25_1-16_Lb"] = "Conte com movimentos ágeis para evitar ser cercado por fantasmas.",
  ["str_guide_circle_N25_2-4_LtT"] = "Cozen",
  ["str_guide_circle_N25_2-4_Lt"] = "Possui uma notável capacidade de se misturar com o ambiente. Às vezes, até parece uma armadilha comum. No entanto, uma vez que se revela, irrompe em uma fúria assassina.",
  ["str_guide_circle_N25_2-4_LbT"] = "Dons do Monstro",
  ["str_guide_circle_N25_2-4_Lb"] = "Geralmente se esconde em Crud. Quando a contagem regressiva termina, ele aparece e ataca os aurorianos.",
  ["str_guide_circle_N25_2-4_RtT"] = "Tática de Abordagem",
  ["str_guide_circle_N25_2-4_Rt"] = "Redefinir os ladrilhos onde o Crud está localizado removerá o Crud e fará um Cozen aparecer.",
  ["str_guide_circle_N26_1-12_RtT"] = "Yoh",
  ["str_guide_circle_N26_1-12_Rt"] = "Outrora o líder do peixe-serpente, ele foi escravizado pelos aurorianos para servir como ferramenta de navegação. Anos de ódio crescente o transformaram em um demônio poderoso.",
  ["str_guide_circle_N26_1-12_LtT"] = "Dons do Monstro",
  ["str_guide_circle_N26_1-12_Lt"] = "Possui poderosas habilidades mágicas e pode controlar projéteis para causar dano aos inimigos.",
  ["str_guide_circle_N26_1-12_LbT"] = "Tática de Abordagem",
  ["str_guide_circle_N26_1-12_Lb"] = "Limpe \"Palavra\" e as réplicas no campo o mais rápido possível para evitar grandes danos.",
  ["str_guide_circle_N27_1-1_RtT"] = "Assistente Afônico",
  ["str_guide_circle_N27_1-1_Rt"] = "Possível um certo tipo de \"mentor\" do Eclipsite, visto que ambos curam outros Eclipsites. A diferença é que este Eclipsite tem mais chances de ficar perto de seus aliados mais volumosos para aproveitar ao máximo o efeito especial de sua habilidade.",
  ["str_guide_circle_N27_1-1_LtT"] = "Dons do Monstro",
  ["str_guide_circle_N27_1-1_Lt"] = "Pode restaurar o HP de outros Eclipsitas. Quanto mais peças ocupadas por outros Eclipsitas dentro do alcance da habilidade do Assistente Afônico, mais forte será o efeito de sua cura.",
  ["str_guide_circle_N27_1-1_LbT"] = "Tática de Abordagem",
  ["str_guide_circle_N27_1-1_Lb"] = "Priorize lidar com o Assistente Afônico e evite que o Assistente Afônico cure os outros Eclipsitas!",
  ["str_guide_circle_N27_1-12_LtT"] = "Verme da areia rosa",
  ["str_guide_circle_N27_1-12_Lt"] = "Um raro verme da areia nativo do Deserto de Rediesel. Ele é coberto de escamas rosa devido a uma mutação única, tornando-o mais poderoso e mais feroz do que outros vermes da areia.",
  ["str_guide_circle_N27_1-12_RtT"] = "Dons do Monstro",
  ["str_guide_circle_N27_1-12_Rt"] = "Perfura o solo para encontrar a localização de seu alvo e, em seguida, explode em campo aberto. Cospe areia preta para atacar os alvos à sua frente.",
  ["str_guide_circle_N27_1-12_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N27_1-12_Rb"] = "Evitar os ataques do Pink Sandworm pode ser complicado! Preste atenção ao seu próprio status o tempo todo e termine a batalha o mais rápido possível!",
  ["str_guide_circle_N27_2-4-1_RbT"] = "guindaste de papel",
  ["str_guide_circle_N27_2-4-1_Rb"] = "Os guindastes de papel podem ser colocados em ladrilhos abissais e os ladrilhos convertidos abaixo deles em ladrilhos cromáticos. Os guindastes de papel desaparecerão depois que a equipe passar por eles.",
  ["str_guide_circle_N27_2-4-2_RbT"] = "Assistência Auroriana",
  ["str_guide_circle_N27_2-4-2_Rb"] = "Pasolo pode colocar guindastes de papel em ladrilhos para ajudar sua equipe a superar situações difíceis. Lembre-se de usar a assistência de habilidade de Pasolo a cada rodada!",
  str_guide_circle_N27_2_1_RtT = "LumoBackup",
  str_guide_circle_N27_2_1_Rt = "Equipes de apoio de Lumopolis juntaram-se à batalha. Pikers aliados agirão após os Eclipsites. O Construtor convocará um Piker quando o jogador lançar a Habilidade Ativa 3 vezes seguidas.",
  str_guide_circle_N27_2_1_RbT = "Aviso!",
  str_guide_circle_N27_2_1_Rb = "Proteja o Construtor aliado primeiro! Assim que o Construtor for derrotado, os Lumo Pikers aliados terão que recuar. A DEF de todos os aurorianos no tabuleiro também será bastante enfraquecida.",
  str_guide_circle_N27_2_2_RbT = "alvo de ataque",
  str_guide_circle_N27_2_2_Rb = "Eclipsites atacarão nosso Lumo Backup primeiro. Assim que todas as equipes Lumo Backup no tabuleiro forem derrotadas, os Eclipsites mudarão de alvo e atacarão o jogador.",
  str_guide_circle_N27_2_2_LbT = "luta de facções",
  str_guide_circle_N27_2_2_Lb = "O Evil Eye do inimigo continuará a convocar os Eclipsites para o campo de batalha. Os jogadores precisam proteger o Construtor aliado e derrotar a Ninhada inimiga.",
  str_guide_circle_N28_3_4_RtT = "Buraco de minhoca",
  ["str_guide_circle_N28_3-4_Rt"] = "Eclipsites podem escapar para outros locais através de buracos de minhoca.",
  ["str_guide_circle_N28_3-4_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_N28_3-4_Rb"] = "Evite que os Eclipsites escapem derrotando-os ou usando habilidades que os forcem a se mover.",
  str_guide_circle_N28_1_12_LtT = "os quatro cavaleiros",
  str_guide_circle_N28_1_12_Lt = "Embora pareçam membros comuns do júri, os capacetes de gesso em suas cabeças os fazem parecer muito suspeitos. Acontece que são Eclipsites escondidos sob eles! O mais confuso é que eles parecem estar seguindo as instruções de alguém...",
  str_guide_circle_N28_1_12_LbT = "Dons do Monstro",
  str_guide_circle_N28_1_12_Lb = "Sempre que 1 dos Quatro Cavaleiros for atacado ou recuperar HP, os outros cavaleiros sofrerão a mesma quantidade de dano ou recuperarão a mesma quantidade de HP.",
  str_guide_circle_N28_1_12_RbT = "Tática de Abordagem",
  str_guide_circle_N28_1_12_Rb = "Observe cuidadosamente a posição dos Quatro Cavaleiros e aja com cautela!",
  str_guide_circle_N29_zhanqi_1_LtT = "Buraco de minhoca",
  str_guide_circle_N29_zhanqi_1_Lt = "Ajuda os Eclipsites a se moverem mais rápido no campo de batalha.",
  str_guide_circle_N29_zhanqi_1_LbT = "Tática de Abordagem",
  str_guide_circle_N29_zhanqi_1_Lb = "Evitar conflito com aurorianos e passar pelo dispositivo de teletransporte o mais rápido possível parece ser uma opção mais sensata.",
  str_guide_circle_N29_1_8_LbT = "Demônio Hati",
  str_guide_circle_N29_1_8_Lb = "Memórias do passado inundaram seu coração, criando o temível Demon Hound quando o ódio assumiu o controle.",
  str_guide_circle_N29_1_8_RbT = "Dons do Monstro",
  str_guide_circle_N29_1_8_Rb = "Demon Hati consome uma parte de seu HP para atacar e recupera uma parte de seu HP perdido se algum auroriano for atingido. Demon Hati causa mais dano à medida que seu HP diminui!",
  str_guide_circle_N29_1_14_LbT = "Demônio Hati",
  str_guide_circle_N29_1_14_Lb = "Memórias do passado inundaram seu coração, criando o temível Demon Hound quando o ódio assumiu o controle.",
  str_guide_circle_N29_1_14_RbT = "Dons do Monstro",
  str_guide_circle_N29_1_14_Rb = "Demon Hati consome uma parte de seu HP para atacar e recupera uma parte de seu HP perdido se algum auroriano for atingido. Demon Hati causa mais dano à medida que seu HP diminui!",
  str_guide_circle_N29_1_14_LbT_2 = "Cuidado!",
  str_guide_circle_N29_1_14_Lb_2 = "Quando Demon Hati está à beira da morte, ela pode consumir energia regenerativa para restaurar seu HP total. Ela também ganhará uma habilidade poderosa e aumentará seus efeitos de habilidade!",
  str_guide_circle_N29_ex3_1_LbT = "Demônio Hati",
  str_guide_circle_N29_ex3_1_Lb = "Memórias do passado inundaram seu coração, criando o temível Demon Hound quando o ódio assumiu o controle.",
  str_guide_circle_N29_ex3_1_RbT = "Dons do Monstro",
  str_guide_circle_N29_ex3_1_Rb = "Demon Hati consome uma parte de seu HP para atacar e recupera uma parte de seu HP perdido se algum auroriano for atingido. Demon Hati causa mais dano à medida que seu HP diminui!",
  str_guide_circle_N29_ex3_1_LbT_2 = "Cuidado!",
  str_guide_circle_N29_ex3_1_Lb_2 = "Quando Demon Hati está à beira da morte, ela pode consumir energia regenerativa para restaurar seu HP total. Ela também ganhará uma habilidade poderosa e aumentará seus efeitos de habilidade!",
  str_guide_circle_N29_ex3_1_RbT_2 = "Aviso!",
  str_guide_circle_N29_ex3_1_Rb_2 = "Demon Hati neutraliza habilidades ativas se os aurorianos as lançarem contra ela.",
  str_guide_warn_11900702 = "Este é o nível de refinamento do equipamento atual. Cada equipamento pode ser refinado 3 vezes.",
  str_guide_warn_11900703 = "Os efeitos de refinamento do equipamento são mostrados aqui. Além de melhorar os atributos básicos, o refinamento também pode aprimorar as habilidades aurorianas.",
  str_guide_warn_11900704 = "Além de atender aos requisitos básicos de desbloqueio para refinamento, os aurorianos também precisam consumir os materiais correspondentes.",
  str_guide_warn_11900802 = "Este é o nível de refinamento do equipamento atual. Cada equipamento pode ser refinado 3 vezes.",
  str_guide_warn_11900803 = "Os efeitos de refinamento do equipamento são mostrados aqui. Além de melhorar os atributos básicos, o refinamento também pode aprimorar as habilidades aurorianas.",
  str_guide_warn_11900804 = "Além de atender aos requisitos básicos de desbloqueio para refinamento, os aurorianos também precisam consumir os materiais correspondentes.",
  str_guide_warn_11900805 = "O Paradigm pode ser obtido por meio de prêmios semanais de Atividade, entre outros métodos. Toque no ícone para ver a lista detalhada de fontes Paradigm.",
  ["str_guide_circle_N30_15-2_RtT"] = "Soldados Illumina",
  ["str_guide_circle_N30_15-2_Rt"] = "Soldados de combate comuns do Exército Illumina, conhecidos por sua habilidade com rifles e facas de combate, bem como sua tenacidade, ética de trabalho, proatividade em batalha e espírito de luta destemido.",
  ["str_guide_circle_N30_15-2_LbT"] = "Dons do Monstro",
  ["str_guide_circle_N30_15-2_Lb"] = "Usa mais ataques à distância. Quando a batalha é intensa, avança rapidamente aos inimigos e enfrenta-os em combate corpo a corpo para derrotá-los o mais rápido possível.",
  ["str_guide_circle_N30_15-2_RbT"] = "Cuidado!",
  ["str_guide_circle_N30_15-2_Rb"] = "Quando o HP estiver abaixo de 50%, todos os ataques com armas se tornarão ataques corpo a corpo com uma faca de combate. Ao mesmo tempo, todos os hematomas acumulados se transformarão em HP restaurado e aumentarão ATK e DEF.",
  ["str_guide_circle_N30_15-9_Lt"] = "Um robô de combate desenvolvido pela Illumina. Ele teve um desempenho extremamente bom em testes internos, mas ainda não foi testado em combate real.",
  ["str_guide_circle_N30_15-9_LtT"] = "Sondador",
  ["str_guide_circle_N30_15-9_Lb"] = "O perfurador tem 2 estados. Ele se move pelo campo em seu estado normal e cava um certo número de Campos de Energia e Campos de Suporte a cada rodada. Quando há um certo número de Campos de Energia no campo, ele absorve e monta uma Plataforma de Perfuração.",
  ["str_guide_circle_N30_15-9_LbT"] = "Características do inimigo",
  ["str_guide_circle_N30_15-9_Rb"] = "Quando há menos Campos de Suporte no campo, o Perfurador escava mais Campos de Suporte.",
  ["str_guide_circle_N30_15-9_RbT"] = "Nota",
  ["str_guide_circle_N30_15-9-2_Lt"] = "Os Campos de Energia são ladrilhos totalmente energizados que podem ser usados para montar a Plataforma do Perfurador. Interrompe a passagem de unidades no terreno quando está presente.",
  ["str_guide_circle_N30_15-9-2_LtT"] = "Campo de energia",
  ["str_guide_circle_N30_15-9-2_Rb"] = "Se houver 6 Campos de Energia no campo de batalha quando o Driller entrar em ação, o Driller acionará uma habilidade especial, construindo uma Plataforma do Driller.",
  ["str_guide_circle_N30_15-9-2_RbT"] = "Peças necessárias para montagem.",
  ["str_guide_circle_N30_16-14_Lt"] = "Como um dos Wraiths mais poderosos, ele ataca com todas as suas forças quando seu status é ameaçado.",
  ["str_guide_circle_N30_16-14_LtT"] = "Figerald",
  ["str_guide_circle_N30_16-14_Lb"] = "Os ladrilhos colapsam depois que os aurorianos se movem sobre eles. Quando não há ladrilhos suficientes no campo de batalha, Figerald libera seu poder para remodelar o espaço e causar dano.",
  ["str_guide_circle_N30_16-14_LbT"] = "Características do inimigo",
  ["str_guide_circle_N30_16-14_Rt"] = "Planeje bem sua rota para minimizar o número de vezes que você sofre dano quando Figerald remodela o espaço.",
  ["str_guide_circle_N30_16-14_RtT"] = "Tática de Abordagem",
  str_guide_circle_N30_tower10_LtT = "caçador mecânico",
  str_guide_circle_N30_tower10_LbT = "Características do inimigo",
  str_guide_circle_N30_tower10_RbT = "Aviso!",
  str_guide_circle_N30_tower10_Lt = "Um antigo guardião criado com o único propósito de proteger os segredos desta terra. É difícil escapar de seus ataques e ele também tem uma auto-recuperação incrível para mantê-lo funcionando através dos tempos. Ninguém vai querer enfrentá-lo sozinho.",
  str_guide_circle_N30_tower10_Lb = "Cria uma zona protegida dentro de 2 grupos circundantes de si mesmo a cada rodada. Os aurorianos dentro da zona protegida sofrerão dano adicional sempre que atacarem ou se moverem. Se o Mechanical Huntsman for invencível quando entrar em ação, ele consumirá sua energia regenerativa para restaurar seu HP total.",
  str_guide_circle_N30_tower10_Rb = "Quando o Mechanical Huntsman entra no estado invencível, ele desencadeia um ataque extremamente perigoso que reduz todos os inimigos na zona protegida a 1 HP na próxima rodada.",
  str_guide_circle_N30_tower10_3_LtT = "bennuguardiano",
  str_guide_circle_N30_tower10_3_Lt = "Um antigo guardião residente nas profundezas do Território Secreto, despertado devido a frequentes distúrbios de intrusos. Mesmo os Eclipsitas têm medo de suas poderosas habilidades. Vaga pelo campo de batalha sem rumo.",
  str_guide_circle_N30_tower10_3_LbT = "Características do inimigo",
  str_guide_circle_N30_tower10_3_Lb = "Possui grande poder. Acumula Fúria quando atacado. Quando Fury atinge um certo nível, entra em um estado Enfurecido, reduzindo o dano recebido e lançando habilidades poderosas adicionais. Se o Bennuguardian for invencível quando entrar em ação, ele consumirá sua energia regenerativa para restaurar seu HP total.",
  str_guide_circle_N30_tower10_3_RbT = "Aviso!",
  str_guide_circle_N30_tower10_3_Rb = "Monitore a Fúria de Bennuguardian o tempo todo e aja com cautela!",
  ["str_guide_circle_15-14_LtT"] = "Helios de teste de estado",
  ["str_guide_circle_15-14_Lt"] = "Depois de viver sozinho por mais de uma década na Dark Zone, este soldado Illumina esqueceu tudo, exceto lutar. O mais assustador é que ele ficou mais forte na batalha depois de ser modificado por alguém...",
  ["str_guide_circle_15-14_RtT"] = "Características do inimigo",
  ["str_guide_circle_15-14_Rt"] = "Uma entidade que possui fortes habilidades de combate e acumula Contusões ao receber dano. Quando seus ataques erram o alvo, uma Marca do Terror é lançada no campo. As habilidades de Helios se tornam mais poderosas com cada Terror Mark no campo.",
  ["str_guide_circle_15-14_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_15-14_Rb"] = "Observe onde estão as marcas para evitar os ataques de Helios!",
  str_guide_circle_621_RtT = "Azulejo de prisma em forma de cruz",
  str_guide_circle_621_Rt = "Quando ele é conectado com outros ladrilhos, os 4 ladrilhos ao seu redor em forma de cruz são convertidos para a mesma cor.",
  ["str_guide_circle_N30_16-9_Lt"] = "Este Eclipsite especial se assemelha a aranhas e aprendeu o comportamento de grupos de aranhas durante seu caminho evolutivo. Ele se esconde na escuridão onde a luz do sol não pode chegar.",
  ["str_guide_circle_N30_16-9_LtT"] = "Rainha Aranha",
  ["str_guide_circle_N30_16-9_Lb"] = "Possuindo fortes habilidades reprodutivas, tece teias de aranha em um ambiente de caça.",
  ["str_guide_circle_N30_16-9_LbT"] = "Dons do Monstro",
  ["str_guide_circle_N30_16-9_Rt"] = "Concentre sua atenção em limpar as teias e limpe os Spider Eggs e Spider Hatchlings convocados pela Rainha Aranha o mais rápido que puder.",
  ["str_guide_circle_N30_16-9_RtT"] = "Tática de Abordagem",
  ["str_guide_circle_N30_16-3_Lt"] = "Um excelente membro da Illumina e especialista em combate corpo a corpo discreto com a capacidade de detectar e reagir aos movimentos do inimigo durante batalhas intensas, permitindo contra-ataques eficazes.",
  ["str_guide_circle_N30_16-3_LtT"] = "Soldado de Elite Illumina",
  ["str_guide_circle_N30_16-3_Lb"] = "Cada vez que o inimigo usa uma habilidade ativa, avança instantaneamente 1 ladrilho em direção ao inimigo e ataca.",
  ["str_guide_circle_N30_16-3_LbT"] = "Habilidade de Contra-ataque",
  ["str_guide_circle_N30_16-3_Rt"] = "Acumula Contusões ao receber dano. Se o jogador não causar dano a esta unidade durante esta rodada, cura imediatamente todos os hematomas para restaurar HP.",
  ["str_guide_circle_N30_16-3_RtT"] = "Aprimoramento tenaz",
  str_guide_warn_12000101 = "O evento Illumination's Descent já está em andamento! Durante o período do evento, o Illumina Supply Center estará aberto a todos os Navegantes!",
  str_guide_warn_12000102 = "Os Passes de Suprimentos obtidos ao gastar o Prisma podem ser trocados por várias recompensas no Centro de Suprimentos Illumina.",
  str_guide_warn_12000103 = "Entre no novo simulador de exercícios militares Team Battle de Gronru para participar de um treinamento abrangente com seus aurorianos!",
  str_guide_warn_12000104 = "Enfrente os estágios da história do evento e complete as missões em seu Livro de Eventos Especiais!",
  str_guide_warn_12000105 = "Lembre-se de entrar no jogo todos os dias para receber as recompensas diárias.",
  str_guide_warn_12000106 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  str_guide_warn_12100101 = "A Jornada ao Passado já começou! Vamos revisitar os velhos tempos com Mia no Dia da Família e descubra a verdade por trás do que aconteceu!",
  str_guide_warn_12100102 = "Em Bottomless Chasm enfrentaremos uma série de difíceis desafios.",
  str_guide_warn_12100103 = "As Gotas de Cristal obtidas ao concluir as etapas do evento e ao gastar o Prisma podem ser usadas para resgatar várias recompensas da Sala de Adivinhação.",
  str_guide_warn_12100104 = "Lembre-se de entrar no jogo todos os dias para obter as recompensas On Memories of Old.",
  str_guide_warn_12100105 = "Enfrente os estágios da história do evento e complete as missões em seu Livro de Eventos Especiais!",
  str_guide_warn_12100106 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  ["str_guide_circle_N31_1-14_Lt"] = "Mime Kartima brande seu escudo, reduzindo o dano de ataques frontais. Perde o efeito quando atordoado, amedrontado, paralisado ou infligido com outros efeitos de controle.",
  ["str_guide_circle_N31_1-14_LtT"] = "Kartima: Shieldguard",
  ["str_guide_circle_N31_1-14_Lb"] = "Mime Kartima fica imune a efeitos de controle por 2 rodadas após entrar na batalha.",
  ["str_guide_circle_N31_1-14_LbT"] = "Kartima: Inflexível",
  ["str_guide_circle_N31_1-14_Rt"] = "Mime Kartima usa o martelo de corrente para atacar uma área à sua frente à direita ou usa o escudo para repelir o alvo à frente à esquerda",
  ["str_guide_circle_N31_1-14_RtT"] = "Técnica de Batalha",
  ["str_guide_circle_N31_1-16_Lt"] = "Ela tem imenso controle sobre o ambiente e é parcialmente resistente a ataques e habilidades normais devido ao efeito do Phantom Crystal.",
  ["str_guide_circle_N31_1-16_LtT"] = "Joshua: Alma Maculada",
  ["str_guide_circle_N31_1-16_Lb"] = "Escolha diferentes estratégias de ação, como usar ataques normais ou habilidades contra Joshua: Tainted Soul na rodada atual com base no efeito do Phantom Crystal.",
  ["str_guide_circle_N31_1-16_LbT"] = "Técnica de Batalha",
  str_guide_popstar_fail_tip = "Estratégia de Eliminação",
  str_guide_popstar_fail_desc = "Use as habilidades aurorianas para remover o máximo de peças possível em cada etapa. Ao remover os ladrilhos, pensar cuidadosamente sobre a condição em que os ladrilhos estarão durante a próxima etapa tornará as coisas infinitamente mais fáceis para você.",
  str_guide_circle_N31_star1_Rt = "Pode ser removido junto com as telhas. Se não for removido, se transforma em um ladrilho quebrado após o término da contagem regressiva.",
  str_guide_circle_N31_star1_RtT = "Rúnica",
  str_guide_circle_N31_star2_Rt = "Ao remover ladrilhos aprimorados, este ladrilho é tratado como um ladrilho removido adicionalmente.",
  str_guide_circle_N31_star2_RtT = "Casa Melhorada",
  str_guide_circle_N31_star3_Rt = "Os ladrilhos bloqueados não podem ter sua cor convertida. Depois de remover os ladrilhos bloqueados, eles são convertidos em ladrilhos normais.",
  str_guide_circle_N31_star3_RtT = "Casa Bloqueada",
  str_guide_warn_6012102 = "Toque p/ ver det. da classificação.",
  str_guide_warn_6012104 = "Toque aqui para ver o Ranking.",
  str_guide_warn_6012106 = "Toque aqui para continuar visualizando.",
  str_guide_warn_6012107 = "Você pode obter Pronunciamentos Esquecidos e Sussurros Esquecidos completando Recompensas de Caça.",
  str_guide_warn_6012108 = "Os navegadores podem trocar Forgotten Utterances e Forgotten Whispers no Exiled Harborage por Solamber, Aurorians e Star Flares.",
  str_guide_warn_6012202 = "Podemos formar várias equipes para desafiar os chefes. O dano total de todas as nossas equipes será registrado como resultado final.",
  str_guide_warn_6012203 = "Nenhuma classificação ou emblema estará disponível se você ainda não iniciou seu desafio.",
  str_guide_warn_6012204 = "Toque p/ ver det. da classificação.",
  str_guide_warn_6012206 = "Toque aqui para ver sua classificação atual.",
  str_guide_warn_6012208 = "Toque aqui para continuar visualizando.",
  str_guide_warn_6012209 = "Você pode obter Pronunciamentos Esquecidos e Sussurros Esquecidos completando Recompensas de Caça.",
  str_guide_warn_6012210 = "Os navegadores podem trocar Forgotten Utterances e Forgotten Whispers no Exiled Harborage por Solamber, Aurorians e Star Flares.",
  str_guide_warn_12200201 = "Huh? Onde estou? Isso é um... outro Cristal da Memória Eterna?",
  str_guide_warn_12200202 = "Não conseguimos sair no final...? Tudo bem! Recite o feitiço de viagem no tempo em voz alta e toque aqui!",
  str_guide_warn_12200301 = "Shush... Alguém parece estar falando por perto. Ahem, eu não estou escutando! Isso se chama... coleta de informações!",
  str_guide_warn_12200401 = "Ver? Eu sabia que estava certo. Temos em nossas mãos algumas informações incríveis! O que? Você não consegue se lembrar de tudo? Então coloque aqui as informações que reunimos!",
  str_guide_warn_12200402 = "Veja, todas as informações estão aqui, agora você não precisa se preocupar em esquecer as coisas! Preste atenção em tudo ao seu redor e preencha todo esse espaço.",
  str_guide_warn_12200101 = "The Edge of Collapse começou! Em A Divergência, vamos investigar o mistério do Cristal da Memória Eterna!",
  str_guide_warn_12200102 = "Enfrentaremos uma série de difíceis desafios no mundo de Shattered Illusion.",
  str_guide_warn_12200103 = "As Lágrimas de Cristal obtidas ao concluir as etapas do evento e ao gastar o Prisma podem ser trocadas por várias recompensas no Hall of Remembrance.",
  str_guide_warn_12200104 = "Lembre-se de entrar no jogo todos os dias para obter as recompensas do Wistful Musing.",
  str_guide_warn_12200105 = "Enfrente os estágios da história do evento e complete as missões em seu Livro de Eventos Especiais!",
  str_guide_warn_12200106 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  str_guide_circle_N33_15_Lt = "Uma borboleta extremamente rara, dizem que só aparece perto do Vale Denuo. É reclusa por natureza, com sentidos altamente aguçados. O poder de combate das Denuo Goddesses adultas não deve ser subestimado.",
  str_guide_circle_N33_15_LtT = "Deusa Denuo",
  str_guide_circle_N33_15_Lb = "Eles catalisam o crescimento das plantas através da polinização, protegendo-se enquanto causam enormes danos aos inimigos.",
  str_guide_circle_N33_15_LbT = "Características do inimigo",
  str_guide_circle_N33_15_Rt = "Escolha seu caminho com sabedoria para evitar que a Deusa Denuo polinize a Erva Encantada Sadesiana, tornando-a mais agressiva.",
  str_guide_circle_N33_15_RtT = "Tática de Abordagem",
  str_guide_circle_chapter18_14_Rb = "Realize ataques intensivos para paralisar o Engine VII Corrompido, atrasando seu ataque ao portão da Fortaleza Illumina.",
  str_guide_circle_chapter18_14_RbT = "Tática de Abordagem",
  str_guide_circle_chapter18_14_Rt = "Originalmente um robô de combate colossal criado pela Illumina, ele se tornou uma das maiores ameaças depois que seu piloto perdeu a razão devido à contaminação pela lama.",
  str_guide_circle_chapter18_14_RtT = "Corrompido Engine VII",
  str_guide_warn_80010102 = "Só você pode entrar nos sonhos de Eva...",
  str_guide_warn_80010103 = "Termine as missões detalhadas nos fragmentos de memória para ganhar Lumamber e descubra histórias ocultas sobre Eve.",
  str_guide_warn_80010104 = "Metamorpha e Fragmentos de Sedimento adquiridos no Sonho podem ser trocados por uma variedade de recompensas aqui, incluindo a roupa de Eve.",
  str_guide_warn_80010105 = "As bijuterias coletadas no Sonho são todas cuidadosamente guardadas aqui por Eve.",
  str_guide_warn_80010106 = "Complete as missões no Dream para adquirir o Stand By Me Set.",
  str_guide_warn_80010107 = "Toque aqui para ver os detalhes.",
  str_guide_warn_80010202 = "Isto parece ser um cálice que me foi dado por alguém especial.",
  str_guide_warn_80010203 = "Eu me lembro, esta taça pode me conceder poderes especiais!",
  str_guide_warn_80010204 = "Hã? O copo está vazio... Eu preciso coletar Ondas de Alegria para encher o copo! Quanto mais eu coletar, mais poder posso ganhar!",
  str_guide_warn_80010205 = "Mas espere... tem alguém na porta?",
  str_guide_circle_80010206 = "O-O que é isso?!",
  str_guide_circle_80010207 = "Não tem problema... não tenho medo! Toque aqui, quero ir e descobrir!",
  str_guide_warn_80010208 = "Eu me pergunto quem é... Eles estão vindo atrás de mim?",
  str_guide_circle_80010304 = "Oh! Encontrei, é... a mesma sombra de antes?",
  str_guide_warn_80010305 = "Essa sombra pode convocar Eclipsites? Agora não posso simplesmente ignorá-lo, posso?",
  str_guide_warn_80010306 = "Meu professor me disse que se o inimigo for muito forte, não se envolva demais na luta. Você pode tentar mudar o nível de dificuldade!",
  str_guide_warn_80010307 = "Pesadelo é mais desafiador que Reverie, mas se eu conseguir completar Pesadelo com 3 estrelas, eu poderia obter Ripples of Joy e melhorar Smiles Lead to Happiness.",
  str_guide_warn_80010308 = "Toda vez que eu enfrentar Omen, minha Raciocínio será afetada...",
  str_guide_warn_80010309 = "Mas não se preocupe! Eu me exercito diligentemente para ficar em forma, então às 05:00 todos os dias, o ponto Wit será recuperado em 3 pontos! Mas uma vez que atinge o limite máximo, não pode ser aumentado mais...",
  str_guide_circle_80010402 = "Encontrei!",
  str_guide_warn_80010403 = "De qualquer forma, vamos deixá-lo de lado por enquanto.",
  str_guide_warn_80010404 = "Depois de coletar tantas coisas, haverá alguma reação mágica entre eles?",
  str_guide_warn_80010405 = "Ah... já ia me esquecendo, ainda preciso ir atrás daquela sombra!",
  str_guide_warn_80010406 = "Deslize a tela para dar uma boa olhada nos arredores!",
  str_guide_warn_80010407 = "Toque aqui para retornar à exibição original.",
  str_guide_warn_80010408 = "Há muito o que fazer, então é melhor manter as informações aqui por enquanto.",
  str_guide_circle_80010501 = "Os adultos nunca me deixam passar por este portão... então o único jeito é arrombá-lo se eu quiser sair?",
  str_guide_circle_80010502 = "Nós vamos descobrir.",
  str_guide_circle_80011101 = "O-O que é isso?! Eles estão tentando causar estragos neste mundo... Humph, não é como se eu estivesse com medo! Toque aqui e eu vou espantá-los pessoalmente!",
  str_guide_warn_80010601 = "Eu me tornei mais forte? As próximas batalhas devem ser um pouco mais fáceis agora.",
  str_guide_warn_80010701 = "Eu adquiri uma habilidade completamente nova? Vou tentar daqui a pouco!",
  str_guide_warn_80010121 = "Hã? O que é isso?",
  str_guide_warn_80010122 = "Uau, parece que dominei um poder único? Hehe, vamos testá-lo! Parece que pode ser usado uma vez a cada duas rodadas!",
  str_guide_warn_80010521 = "Eh, meu poder mudou?",
  str_guide_warn_80010522 = "Escolha uma área? Isso não parece difícil. Eu tenho você coberto!",
  str_guide_warn_80010931 = "Dominou um novo poder?",
  str_guide_warn_80010932 = "Tudo bem, vamos fazer isso!",
  str_guide_warn_80011331 = "Meu poder mudou novamente...",
  str_guide_warn_80011332 = "Parece que agora posso liberar esse poder sem descanso...",
  str_guide_warn_80011631 = "Eu dominei mais um poder!",
  str_guide_warn_80011632 = "Com esse poder, não hesitarei mais!",
  str_guide_warn_12300101 = "Parece que você está feliz com o resort. Posso conversar com você em particular, então?",
  str_guide_warn_12300201 = "As instalações produziram novas Pass Coins novamente. Você precisa coletar e usá-las para formar um círculo virtuoso.",
  str_guide_warn_12300202 = "As Moedas de Passe do Distrito do Hotel estão prontas para serem coletadas. É trabalho do assistente descobrir como usá-las de forma eficiente.",
  str_guide_warn_12300203 = "Você está me perguntando como usar as Pass Coins? Basta usá-las para melhorar as instalações diretamente. Instalações atualizadas também produzirão Pass Coins em uma taxa mais rápida. É assim que as empresas usam dinheiro para ganhar mais dinheiro.",
  str_guide_warn_12300204 = "Você quer saber por que não pode coletar todas as Moedas de Passe de uma vez? Isso se deve a considerações de segurança. O principal é que é mais tranquilizador pegá-las uma por uma e segurá-las!",
  str_guide_warn_12300205 = "Você ainda se lembra de como melhorar as instalações? Vamos tentar agora!",
  str_guide_warn_12300301 = "Para melhorar uma instalação, você precisa de Pass Coins e atender a certas condições. Vejamos... Sim! Esta pode ser melhorada agora.",
  str_guide_warn_12300302 = "Instalações atualizadas se tornarão mais populares e poderão produzir Pass Coins de forma mais eficiente. A melhoria das instalações também desbloqueará aventuras com outros Aurorianos e melhorará as recompensas.",
  str_guide_warn_12300303 = "Toque aqui para assinar o plano de melhoria e concluir o upgrade.",
  str_guide_warn_12300401 = "Foi atualizado agora! Eu também coletei as Moedas de Passe que você esqueceu de coletar antes para você. De nada!",
  str_guide_warn_12300501 = "Acho que você desbloqueou aventuras com outros Aurorianos. Vamos conferir.",
  str_guide_warn_12300601 = "Parece que uma garota linda, inteligente, gentil e agradável está esperando por você.",
  str_guide_warn_12300701 = "Quanto a como desbloquear aventuras com Aurorianos... Eu não preciso te ensinar isso, não é?",
  str_guide_warn_12300801 = "Você pode ver aventuras desbloqueadas e revisar aventuras que já vivenciou no Guia de Aventuras.",
  str_guide_warn_12300802 = "Se tiver alguma dúvida sobre o funcionamento do resort, pode consultar o manual que preparei especialmente para você.",
  str_guide_warn_12400101 = "O evento Valley Oasis já começou! Durante as atrações diurnas, exploraremos várias instalações do país das maravilhas.",
  str_guide_warn_12400102 = "Durante as Festas Noturnas, enfrentaremos desafios mais difíceis no parque de diversões sob o manto da escuridão.",
  str_guide_warn_12400103 = "Em Park Tycoon, seremos responsáveis pela gestão do parque de diversões. Certifique-se de cuidar bem dele!",
  str_guide_warn_12400104 = "Os Tokens da Claw Machine obtidos ao concluir as etapas do evento e gastar o Prism podem ser usados para resgatar várias recompensas das Claw Machines.",
  str_guide_warn_12400105 = "Lembre-se de entrar no jogo todos os dias para obter as recompensas do Contador de Login de Convidado.",
  str_guide_warn_12400106 = "Enfrente os estágios da história do evento e complete as missões em seu Livro de Eventos Especiais!",
  str_guide_warn_12400107 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  str_guide_warn_12500101 = "Uma Sinfonia de Gloaming já está disponível. Vamos completar a missão de seus amigos Illumina no jogo Twilight Tactics e reconstruir a cidade!",
  str_guide_warn_12500102 = "Na jogabilidade On the Cusp of Gloom, enviaremos uma equipe avançada para a investigação perto da zona crepuscular para descobrir o plano dos Eclipsites!",
  str_guide_warn_12500103 = "Lembre-se de entrar no jogo todos os dias para obter recompensas de login do New Forces.",
  str_guide_warn_12500104 = "Enfrente os estágios da história do evento e complete as missões em seu Livro de Eventos Especiais!",
  str_guide_warn_12500105 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  str_guide_warn_10181401 = "A durabilidade do Stronghold Gate é exibida aqui. Lance seus foguetes quando o Motor Corrompido VII avançar perto do Portão.",
  str_guide_circle_80010521_Lb = "Este é o que está segurando a boneca. Quando derrotado, causa dano a todos os Eclipsites no campo e passa aleatoriamente no boneco. Quando outros Eclipsites são derrotados primeiro, o portador da boneca ganha um escudo de contagem.",
  str_guide_circle_80010521_LbT = "causa lúdica",
  str_guide_circle_80010521_Rb = "Desvende ilusões com a Boneca!",
  str_guide_circle_80010521_RbT = "Boneca Desgastada",
  str_guide_circle_80010621_Lt = "No início da batalha, Forest Evil Eyes ficará adormecido por 3 rodadas, e outros Evil Eyes enfrentarão uma diminuição substancial na DEF durante esse período. Ao ser atacado, o Evil Eye despertará.",
  str_guide_circle_80010621_LtT = "Diligente",
  str_guide_circle_80010621_Lb = "Antes de sairmos, deixe-me fazer uma pausa...",
  str_guide_circle_80010621_LbT = "Boneca Desgastada",
  str_guide_circle_80010721_Lt = "Se os escudos de contagem não estiverem todos quebrados até o final da rodada, este inimigo causa dano fixo ao jogador uma vez.",
  str_guide_circle_80010721_LtT = "Fúria Narcisista",
  str_guide_circle_80010721_Rt = "Esta é... a única maneira de chamar sua atenção?",
  str_guide_circle_80010721_RtT = "Boneca Desgastada",
  str_guide_circle_80010821_Lt = "O chefe acumula energia a cada 3 rodadas. Cada pilha de energia concede um bônus de 3% de ATK. Se todas as pilhas não forem removidas até o final da rodada, o chefe adquirirá 8 pilhas de escudo de contagem.",
  str_guide_circle_80010821_LtT = "Punho de Ferro",
  str_guide_circle_80010821_Rt = "Atravesse... a jaula... só para... te acordar...",
  str_guide_circle_80010821_RtT = "Boneca Desgastada",
  str_guide_circle_80010821_Rb = "Cada vez que o chefe for atacado, 1 pilha da marca será removida. Essas marcas de energia aumentam significativamente o ATK e a capacidade de sobrevivência do chefe, portanto, lidar com elas o mais rápido possível é crucial!",
  str_guide_circle_80010821_RbT = "Tática de Abordagem",
  str_guide_circle_80011021_Rt = "Todos os inimigos ganham um aumento significativo no ATK. Os aurorianos podem restaurar seu HP infligindo dano aos inimigos de forma consistente.",
  str_guide_circle_80011021_RtT = "Contra-ataque Mortal",
  str_guide_circle_80011021_Rb = "Qual a diferença entre parar e desistir?",
  str_guide_circle_80011021_RbT = "\"Eve\"",
  str_guide_circle_80011121_Rt = "A equipe pode usar o Conveyor Vortex para se teletransportar para qualquer lugar no campo e lançar Chain Combos. Aumenta o dano do Chain Combo.",
  str_guide_circle_80011121_RtT = "Combo grátis",
  str_guide_circle_80011121_Rb = "Venha comigo. Você pode ir aonde quiser.",
  str_guide_circle_80011121_RbT = "\"Eve\"",
  str_guide_circle_80011421_Rt = "A geração de runas é ineficiente, e a Sombra agora convocará Shadowgeists diretamente.",
  str_guide_circle_80011421_RtT = "Características do inimigo",
  str_guide_circle_80011421_Rb = "Ao conectar as peças, o dano causado pelos aurorianos aumentará bastante, incluindo ataques normais e efeitos de dano adicionais.",
  str_guide_circle_80011421_RbT = "Características da equipe",
  str_guide_circle_80011521_Rt = "Derrote Enferno para limpar o palco. Spellhound continuará reaparecendo antes que Enferno seja derrotado.",
  str_guide_circle_80011521_RtT = "Características do inimigo",
  str_guide_circle_80010921_Lb = "Todos os Eclipsites presentes podem reaparecer uma vez. Quando um Eclipsite morre, todos os Eclipsites restantes no campo recebem um aumento no ATK.",
  str_guide_circle_80010921_LbT = "Características do inimigo",
  str_guide_circle_80010921_Rb = "Quanto mais você luta, mais dói.",
  str_guide_circle_80010921_RbT = "\"Eve\"",
  str_guide_circle_80011321_Lb = "O número de pilhas da Marca de Penetrabilidade aumentará significativamente com as habilidades do inimigo, mas cada ataque do jogador reduzirá a Marca de Penetrabilidade em uma pilha.",
  str_guide_circle_80011321_LbT = "Características do inimigo",
  str_guide_circle_80011321_Rb = "O efeito negativo das Marcas de Penetrabilidade é bastante aumentado. Certifique-se de reduzir o número de Marcas de Penetrabilidade atacando o inimigo o mais rápido possível!",
  str_guide_circle_80011321_RbT = "Tática de Abordagem",
  str_guide_circle_80011621_Lb = "A partir desta etapa, a equipe ganha inscrições especiais. Cada vez que o inimigo sofre dano antes de a equipe conectar os blocos, o ataque de todos os aurorianos da equipe aumenta em 1% nessa rodada!",
  str_guide_circle_80011621_LbT = "O último crescimento",
  ["str_guide_circle_CN2-18_Lt"] = "A dor do isolamento e o medo de ser cortado, aquelas memórias insuportáveis do passado, moldaram a pessoa conhecida como Eve hoje.",
  ["str_guide_circle_CN2-18_LtT"] = "luto Eve",
  ["str_guide_circle_CN2-18_Rt"] = "No início de cada rodada, evoque um Dawn Floresça em um local definido para restaurar HP; cada Dawn A flor concede um impulso extra de recuperação.",
  ["str_guide_circle_CN2-18_RtT"] = "Características do inimigo",
  ["str_guide_circle_CN2-18_Rb"] = "Em rodadas específicas, Eve receberá um grande número de pilhas de imunidade. É essencial reduzir essas pilhas o máximo possível através de dano de alta frequência; caso contrário, na próxima rodada, uma quantidade significativa de HP será restaurada com base no número restante de pilhas.",
  ["str_guide_circle_CN2-18_RbT"] = "Descrição da habilidade",
  str_guide_circle_N34_18_1_RtT = "Médico da Illumina",
  str_guide_circle_N34_18_1_Rt = "Onde quer que o Médico Illumina esteja, o moral aumenta, pois os camaradas sabem que suas feridas não ficarão sem tratamento. A Federação Illumina, ciente deste fato, fornece a esses médicos proteção aprimorada, aumentando significativamente suas capacidades de sobrevivência.",
  str_guide_circle_N34_18_1_LbT = "Dons do Monstro",
  str_guide_circle_N34_18_1_Lb = "Um Soldado Illumina sem capacidades de combate. Restaura HP para um Soldado Illumina próximo e restaura uma certa parte de sua própria Contusão.",
  str_guide_circle_N34_18_1_RbT = "Cuidado!",
  str_guide_circle_N34__18_1_Rb = "Ao receber dano, o Médico Illumina acumulará Contusões equivalentes a 50% do dano recebido. Além disso, sua DEF aumenta conforme seu HP diminui.",
  str_guide_circle_N34_18_2_RtT = "Sinalizador Illumina",
  str_guide_circle_N34_18_2_Rt = "Equipado com um comunicador compacto, o Sinaleiro de Illumina carrega uma carga pesada. Por isso, a Federação Illumina desenvolveu um aparato de suporte especializado, facilitando a transmissão de sinais em movimento, o que é a origem do nome desta unidade.",
  str_guide_circle_N34_18_2_LbT = "Dons do Monstro",
  str_guide_circle_N34_18_2_Lb = "Um Soldado Illumina sem capacidades de combate, mas capaz de invocar reforços Illumina no campo de batalha.",
  str_guide_circle_10170901_RtT = "Tecelão do Pavor",
  str_guide_circle_10170901_Rt = "Movido por uma obsessão em aniquilar tudo, ele ignora a depleção de sua própria energia, perseguindo incansavelmente o objetivo, mesmo que isso signifique caminhar gradualmente em direção à sua própria ruína.",
  str_guide_circle_10170901_LbT = "Detalhes da Habil. Passiva",
  str_guide_circle_10170901_Lb = "Toda vez que o movimento da equipe terminar, o Dreadweaver fará com que a equipe mude imediatamente suas posições, afetando a realização dos Combos.",
  str_guide_circle_10170901_RbT = "Características do Ataque",
  str_guide_circle_10170901_Rb = "Quando o HP do Dreadweaver cair abaixo de 50%, ele iniciará um ritual de sacrifício. Na próxima rodada, ele queimará quase todo o seu HP, causando um enorme dano verdadeiro aos jogadores. Este efeito só pode ser acionado uma vez.",
  str_guide_circle_2002901_RtT = "Tanque Illumina L5",
  str_guide_circle_2002901_Rt = "Criado através de modificações em caminhões, o Tanque Illumina L5 possui uma armadura leve, tornando-o perfeito para fabricação em massa. Seu poder de carga e canhões de disparo rápido eliminam rapidamente as unidades leves inimigas.",
  str_guide_circle_2002901_LbT = "Características do inimigo",
  str_guide_circle_2002901_Lb = "Com base nas posições inimigas, opta por disparar uma rápida saraivada de tiros ou uma investida para ataque.",
  str_guide_circle_2003001_RtT = "Lança-chamas Illumina",
  str_guide_circle_2003001_Rt = "\"Reduzir todos os adversários a cinzas\" - Eles epitomizam a eficiência e a impiedade das forças Illumina. Diante das chamas furiosas, toda vida está em pé de igualdade.",
  str_guide_circle_2003001_LbT = "Características do inimigo",
  str_guide_circle_2003001_Lb = "Acumula Contusões ao receber dano. Causa dano a todos os alvos dentro do alcance de ataque, infligindo Queimar neles e criando incêndios.",
  str_guide_circle_2003401_RtT = "Soldado Illumina Corrompido",
  str_guide_circle_2003401_Rt = "Uma vez aliados, agora inimigos - tal é o terror do Eclipse. A única misericórdia restante é colocá-los para descansar.",
  str_guide_circle_2003401_LbT = "Características do inimigo",
  str_guide_circle_2003401_Lb = "Se o HP estiver abaixo de 40% no início de uma rodada, a unidade tem seu ACT e DEF aumentados e seu estilo de ataque alterado.",
  str_guide_circle_2003101_RtT = "Sargento Illumina",
  str_guide_circle_2003101_Rt = "Como oficiais de base do exército Illumina, eles são responsáveis por comandar soldados regulares no campo de batalha. A maioria deles se forma em academias militares, enquanto alguns são promovidos das fileiras de veteranos experientes.",
  str_guide_circle_2003101_LbT = "Características do inimigo",
  str_guide_circle_2003101_Lb = "A presença deles melhora as habilidades dos Soldados Illumina próximos e ajuda na recuperação de seus ferimentos. Caso se encontrem isolados dos aliados ou em combate corpo a corpo com inimigos, esses sargentos pegam em armas, causando danos com cortes devastadores e chutes impactantes.",
  str_guide_circle_2003101_RbT = "Tática de Abordagem",
  str_guide_circle_2003101_Rb = "Derrote primeiro o comandante inimigo!",
  str_guide_circle_2905701_RtT = "Mudbundle",
  str_guide_circle_2905701_Rt = "Dizem ser uma criação de um membro do Eclipse, este Eclipsita é uma fusão de várias características biológicas. Ele cria pântanos aterrorizantes que podem devorar tudo e contaminar tudo o que toca.",
  str_guide_circle_2905701_LbT = "Características do inimigo",
  str_guide_circle_2905701_Lb = "Cria atoleiros e submerge por dentro, obstruindo e interrompendo os movimentos dos Aurorianos, alterando o terreno.",
  str_guide_circle_2905701_RbT = "Tática de Abordagem",
  str_guide_circle_2905701_Rb = "Evite passar por muitos atoleiros. Use suas habilidades para limpar o campo!",
  str_guide_circle_29057011_RtT = "Pântano",
  str_guide_circle_29057011_Rt = "Contaminando tudo o que viu...",
  str_guide_circle_29057011_LbT = "Características",
  str_guide_circle_29057011_Lb = "Ao passar por um certo número de charcos, aumentará o tempo de espera das Habilidades Ativas de todos os Aurorianos.",
  str_guide_circle_29057011_RbT = "Tática de Abordagem",
  str_guide_circle_29057011_Rb = "Pode ser limpo pelas Habilidades de Dano em Área dos Aurorianos",
  str_guide_warn_815000101 = "Por que ainda não consigo me libertar deste sonho? Será por causa de Paloma... ela ainda está presa nele?\nToque no botão Alternar para mudar para o Modo de Passeio. Navegador, você pode ajudar Paloma como me ajudou?",
  str_guide_warn_815000102 = "Toque no botão Alternar novamente para voltar ao Modo Revelar. Navegador, parece que podemos retornar ao meu sonho sempre que quisermos!",
  str_guide_circle_80020201 = "Toque na balança aqui para me ajudar a mergulhar em uma contemplação e dedução mais profundas. Somente após completar minhas deduções posso continuar com as tarefas atribuídas pelo Juiz Chefe.",
  str_guide_circle_80020202 = "No entanto, antes de começar a dedução, preciso reunir evidências e depoimentos suficientes... Observe atentamente. As pistas cruciais devem estar por perto!",
  ["str_guide_circle_CN5-15_Lt"] = "Herdando os sinceros ensinamentos de seu pai e cumprindo todas as suas expectativas, ela se tornou a perfeita Irridon, a maior Juíza Chefe que já se conheceu!",
  ["str_guide_circle_CN5-15_LtT"] = "Irridon: Eximius",
  ["str_guide_circle_CN5-15_Rt"] = "Antes de cada Chain Combo, forma o Escudo de Luz, bloqueando dano equivalente a uma porcentagem do HP máximo.",
  ["str_guide_circle_CN5-15_RtT"] = "Escudo de Luz",
  ["str_guide_circle_CN5-15_Lb"] = "Manipulando e enganando os outros com seus clones - esses truques não são desonrosos aos olhos dela; afinal, ela detém a autoridade máxima como a maior Juíza Chefe.",
  ["str_guide_circle_CN5-15_LbT"] = "Irridon: Clone Exímio",
  ["str_guide_circle_CN5-15_Rb"] = "O dano causado a Irridon: Clones Eximius é transferido instantaneamente para Irridon: Eximius.",
  ["str_guide_circle_CN5-15_RbT"] = "Transmissão de Danos",
  ["str_guide_circle_CN5-18_Lb"] = "Situado fora do campo, imune a ataques normais, só pode ser atacado por habilidades de alvo único.",
  ["str_guide_circle_CN5-18_LbT"] = "Irridon: Clone Exímio",
  ["str_guide_circle_CN5-diaoxiang_Lt"] = "Estátua nobre arrogante. Ela inflige 1 pilha de Preconceito nos aliados e desmorona ao toque, transformando a casa em que estavam em uma casa cromática e removendo 1 pilha de Preconceito.",
  ["str_guide_circle_CN5-diaoxiang_LtT"] = "Estátua do Jurado",
  ["str_guide_circle_CN5-4_Rb"] = "Inimigos específicos possuem o efeito Escudo de Luz. Antes de cada Combo em Cadeia, eles formam o Escudo de Luz, bloqueando dano igual a uma porcentagem de seu HP máximo.",
  ["str_guide_circle_CN5-4_RbT"] = "Escudo de Luz",
  ["str_guide_circle_CN5-8_Lt"] = "Arrogância, preconceito e pensamentos corrompidos... se transformaram em espectros malévolos vagando por Lumópolis, infiltrando-se em cada fenda desta cidade eterna.",
  ["str_guide_circle_CN5-8_LtT"] = "Espectro Carmesim",
  ["str_guide_circle_CN5-8_Lb"] = "Pode se teletransportar para a localização do jogador mais próximo, desferindo vários golpes prejudiciais e empurrando o jogador para trás. Quanto mais longe ele se teletransporta, menos ataques ele lança.",
  ["str_guide_circle_CN5-8_LbT"] = "Características do inimigo",
  ["str_guide_circle_CN5-8_Rb"] = "O Espectro Carmesim pode atrapalhar as posições dos jogadores, então é aconselhável eliminá-lo rapidamente ou se afastar dele.",
  ["str_guide_circle_CN5-8_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_n35-7_LtT"] = "Fera do Gelo",
  ["str_guide_circle_n35-7_Lt"] = "Com pelos e garras afiadas, esse tipo de Eclipsitas se assemelha incrivelmente a feras selvagens, tornando-os bem adaptados para se infiltrar em várias regiões de fronteira para rastreamento, reconhecimento e caça.",
  ["str_guide_circle_n35-7_Lb"] = "Ele seleciona diferentes habilidades com base na posição do Auroriano e, se seu ataque não alcançar nenhum Auroriano, ele escolherá recuperar seu próprio HP.",
  ["str_guide_circle_n35-7_LbT"] = "Características do inimigo",
  ["str_guide_circle_n35-7_Rb"] = "Fique de olho no alcance de ataque dos Eclipsitas e sempre preste atenção na posição dos nossos aliados!",
  ["str_guide_circle_n35-7_RbT"] = "Tática de Abordagem",
  ["str_guide_circle_n35-9_LtT"] = "No. 33",
  ["str_guide_circle_n35-9_Lt"] = "Uma Aurorian do passado distante, encarregada de guardar as ruínas subterrâneas do Norte. Seu Modelo de Eco apresenta erros constantes devido aos danos sofridos e à sua ativação não convencional.",
  ["str_guide_circle_n35-9_Lb"] = "Capaz de se teleportar e alterar o layout dos ladrilhos, além de absorver energia dos ladrilhos para atacar os Aurorianos. Quanto mais ladrilhos disponíveis para absorver energia, maior será o dano.",
  ["str_guide_circle_n35-9_LbT"] = "Características do inimigo",
  ["str_guide_circle_n35-9_Rb"] = "Preste atenção na distribuição dos ladrilhos no campo de batalha e fique atento quando o inimigo usar habilidades!",
  ["str_guide_circle_n35-9_RbT"] = "Tática de Abordagem",
  str_guide_circle_n35_trap5352031_RtT = "Bomba Fatal",
  str_guide_circle_n35_trap5352031_Rt = "Explode sempre que um certo tempo passar, causando dano a todas as unidades no campo de batalha.",
  str_guide_circle_n35_trap5352031_RbT = "Tática de Abordagem",
  str_guide_circle_n35_trap5352031_Rb = "Comande seus Aurorianos para derrotar os inimigos o mais rápido possível, ou você sofrerá dano ao longo do tempo.",
  str_guide_warn_53540034 = "Aqui é exibida a contagem regressiva restante para o Reino.",
  str_guide_warn_16000101 = "Um Enigma Selado em Gelo já está disponível! É hora de conhecer novos parceiros e embarcar na aventura da expedição Through the Snow!",
  str_guide_warn_16000102 = "Em Fatal Trek enfrentaremos uma série de desafios mais complexos.",
  str_guide_warn_16000103 = "No evento Ancient Yurt, podemos trocar Ancient Remains por Solamber, Aurorians 5 estrelas e outros itens valiosos. Ancient Remains podem ser obtidos completando fases do evento e consumindo Prism.",
  str_guide_warn_16000104 = "O novo modo Zarya’s Closet estará disponível. Toque na entrada deste novo modo de jogo para explorá-lo!",
  str_guide_warn_16000105 = "Enfrente os estágios da história do evento e complete as missões em seu Livro de Eventos Especiais!",
  str_guide_warn_16000106 = "Lembre-se de entrar no jogo todos os dias para receber as recompensas diárias de login.",
  str_guide_warn_16000107 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  str_guide_warn_9700101 = "A lista de desejos está disponível neste recrutamento por tempo limitado. Toque para abrir a interface da lista de desejos.",
  str_guide_warn_9700106 = "A Lista de Desejos está disponível exclusivamente no recrutamento a que pertence.",
  str_guide_warn_9700107 = "Neste recrutamento, há um Auroriano com maior probabilidade de obtenção que é fixada no primeiro lugar da lista de desejos, ocupando 50% de chance em todos os Aurorianos de 6 estrelas disponíveis.",
  str_guide_warn_9700108 = "Selecione um Auroriano de 6 estrelas de cada um dos quatro elementos, e cada um deles terá 12,5% de chance de obter Aurorianos de 6 estrelas.",
  ["str_guide_circle_n36-9_LtT"] = "Imperador do Fim",
  ["str_guide_circle_n36-9_Lt"] = "O Supremo Imperador do Caos, pai de Tohru, veterano de muitas guerras, é uma potência inegável, não importa quando e onde.",
  ["str_guide_circle_n36-9_Lb"] = "Com força formidável, ele empunha uma infinidade de habilidades para atacar jogadores com precisão ou desencadear ataques de longo alcance, ao mesmo tempo em que os repele.",
  ["str_guide_circle_n36-9_LbT"] = "Características do inimigo",
  ["str_guide_circle_n36-9_Rb"] = "O Imperador do Fim pode ser influenciado pelas habilidades de empurrão ou teletransporte do jogador. Deslocá-lo no momento certo permite ao jogador evitar ou interromper suas habilidades de ataque.",
  ["str_guide_circle_n36-9_RbT"] = "Tática de Abordagem",
  str_guide_warn_17000101 = "A Folga da Empregada Dragão já está disponível! Hora de conhecer novos amigos e embarcar em uma nova aventura em O Caminho de Casa!",
  str_guide_warn_17000102 = "Gaste Prismas em estágios principais e de Incursão: Recursos para obter Pratos Rasos.",
  str_guide_warn_17000103 = "Use Pratos Rasos para receber diversos prêmios na Cozinha de Tohru.",
  str_guide_warn_17000104 = "Durante o evento, participe do Chá das Celestitas para quizzes de relacionamento com os Aurorianos!",
  str_guide_warn_17000105 = "Lembre-se de entrar no jogo todos os dias para receber as recompensas diárias.",
  str_guide_warn_17000106 = "Enfrente os desafios do evento e complete as missões do seu Livro do Evento Especial!",
  str_guide_warn_17000107 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  str_guide_warn_18000101 = "Veneno Flui Pelos Corações Corrompidos está disponível agora! Hora de conhecer novos amigos e embarcar em uma nova aventura na Clínica Subterrânea!",
  str_guide_warn_18000102 = "Em Bleak Past, enfrentaremos uma série de desafios mais complexos.",
  str_guide_warn_18000103 = "Completar etapas do evento e gastar Prism concede Potes de Coleção, que podem ser usados para resgatar várias recompensas da Sala Secreta.",
  str_guide_warn_18000104 = "Enfrente os estágios da história do evento e complete as missões em seu Livro de Eventos Especiais!",
  str_guide_warn_18000105 = "Lembre-se de entrar no jogo todos os dias para receber as recompensas diárias de login.",
  str_guide_warn_18000106 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  ["str_guide_circle_CN7-15_Lt"] = "Do mundo da superfície à cidade subaquática, um nobre dominador e vilão.",
  ["str_guide_circle_CN7-15_LtT"] = "Rei Tritão",
  ["str_guide_circle_CN7-15_Rt"] = "Ataques causam efeito de empurrão. Pode invocar canhões de salva na borda do campo de batalha.",
  ["str_guide_circle_CN7-15_RtT"] = "Características do inimigo",
  ["str_guide_circle_CN7-15_Lb"] = "Preste atenção ao alcance de ataque das armas de salva ao redor do campo de batalha. Derrote a artilharia de maneira oportuna para encerrar rapidamente a batalha.",
  ["str_guide_circle_CN7-15_LbT"] = "Tática de Abordagem",
  ["str_guide_circle_CN7-5_Lt"] = "Um Eclipsita que se assemelha a um cano de arma. Fornece suporte aos seus companheiros e ataca sua equipe pesadamente!",
  ["str_guide_circle_CN7-5_LtT"] = "Pistola Salva",
  ["str_guide_circle_CN7-5_Rt"] = "Atira em inimigos dentro do alcance de ataque. Se não houver alvos disponíveis, seu ataque é aprimorado e cura o Rei Tritão.",
  ["str_guide_circle_CN7-5_RtT"] = "Canhão Pesado",
  ["str_guide_circle_CN7-7_Lt"] = "Aliados não podem se conectar através dele, nem as unidades inimigas terrestres, mas isso não afeta o efeito de qualquer habilidade lançada.",
  ["str_guide_circle_CN7-7_LtT"] = "Muro Proibido",
  str_guide_circle_80030101 = "Com os binóculos, você pode ver o grandioso castelo à distância - o templo do Senhor das Águas.",
  str_guide_warn_80030102 = "Toque no botão Construção do Templo e Connolly irá para um lugar com uma vista perfeita do templo, junto com seus tentáculos confiáveis, para continuar o projeto de restauração do templo.",
  str_guide_warn_80030301 = "Navegador, bem-vindo ao Ritual de Fusão! Coloque o Fragmento de Água na área de fusão no centro do Ritual de Fusão para me ajudar a completar o ritual, restaurando a força dos Antons!",
  str_guide_warn_80030302 = "O Pedaço de Hidrocristal contém o poder de Anton. Cada Pedaço possui uma quantidade diferente de poder de fusão. Sob condições específicas, alguns pedaços podem liberar poder adicional.",
  str_guide_warn_80030303 = "Arraste o Pedaço de Hidrocristal para um local elegível na área de fusão. Depois de posicioná-lo com sucesso, o Ritual de Fusão guiará e extrairá o poder de fusão contido nele.",
  str_guide_warn_80030304 = "Após posicionar com sucesso o Fragmento de Água, você pode tocar para selecionar e mover ou ajustá-lo. Explore diferentes posições para extrair mais poder de agregação.",
  str_guide_warn_80030305 = "Enquanto selecionado, toque no botão Girar para girar o fragmento 90 graus no sentido anti-horário.",
  str_guide_warn_80030306 = "Enquanto selecionado, toque no botão Cancelar para recuperar o fragmento.",
  str_guide_warn_80030307 = "Aqui, você encontrará o poder total de fusão contido nos Fragmentos de Água atualmente colocados e o poder de fusão necessário para completar este Ritual de Fusão!",
  str_guide_warn_80030308 = "Toque no botão Limpar para remover todos os Fragmentos de Água colocados. Tenha cuidado!",
  str_guide_warn_80030309 = "Quando a energia de fusão atender aos requisitos para o Ritual de Fusão, toque no botão Concluir para finalizar o ritual e restaurar a força de Anton!",
  str_guide_warn_18100101 = "Por favor, me ajude a dar uma olhada! O que no mundo está acontecendo aqui!",
  str_guide_warn_18100102 = "Aqui é onde você pode começar seu treinamento! Complete os estágios de treinamento para ganhar pontos e recompensas de estágio!",
  str_guide_warn_18100103 = "Por favor, note: Durante o módulo de treinamento, existem laços entre certos Aurorians. Quando Aurorians com um vínculo são implantados ao mesmo tempo, eles ganharão mais oportunidades de se envolver em combate.",
  str_guide_warn_18100104 = "Quando pelo menos 3 Aurorianos de uma facção designada são implantados, remover vários ladrilhos de uma vez durante o treinamento pode ativar habilidades de suporte da facção.",
  str_guide_warn_18100105 = "Ao completar o treinamento, você ganhará pontos e, uma vez que atingir um número especificado de pontos por sessão, receberá recompensas especiais.",
  str_guide_warn_18100106 = "Ao completar os estágios de treinamento, você ganhará recompensas. A quantidade máxima de recompensas que você pode obter em cada sessão será exibida aqui.",
  str_guide_warn_18100107 = "Se tiver alguma dúvida, pode ver a descrição detalhada aqui.",
  str_guide_warn_18100108 = "O número total de rodadas em cada ciclo de treinamento é limitado, e o HP total das equipes de um estágio para outro será acumulado.",
  str_guide_circle_N37boss_Lt = "As veias dela pulsam com veneno carmesim, pronta para erradicar qualquer ameaça à sua família, inclusive ela mesma.",
  str_guide_circle_N37boss_LtT = "Rebecca Pântano Venenoso",
  str_guide_circle_N37boss_Rt = "Inflige o efeito de Fusão, fazendo com que os alvos afetados percam HP no início de suas rodadas.",
  str_guide_circle_N37boss_RtT = "Características do inimigo",
  str_guide_circle_N37boss_Lb = "Aproveite ao máximo os Ladrilhos Escuros transformados pelas Marcas de Veneno e cause dano no momento certo.",
  str_guide_circle_N37boss_LbT = "Tática de Abordagem",
  str_guide_circle_N37cap_Lt = "O líder peculiar de uma gangue, habilidoso com armas de fogo. Sua presença significa apenas problemas para Umbraton.",
  str_guide_circle_N37cap_LtT = "Capitão da gangue",
  str_guide_circle_N37cap_Rt = "Ataca após se afastar do alvo, causando dano 2 vezes. Pode roubar os atributos do alvo.",
  str_guide_circle_N37cap_RtT = "Características do inimigo",
  str_guide_circle_N37cap_Lb = "Preste atenção na distância entre você e os inimigos e derrote-os a tempo.",
  str_guide_circle_N37cap_LbT = "Tática de Abordagem",
  str_guide_circle_N37ranger_Lt = "Precisas, seguras, discretas e incrivelmente poderosas, as bestas se tornaram uma arma adorada entre os gangsters devido a essas propriedades incomparáveis. Inimigos habilidosos em seu uso costumam ser altamente perigosos.",
  str_guide_circle_N37ranger_LtT = "Arqueiro da Gangue",
  str_guide_circle_N37ranger_Rt = "Pode atacar alvos em forma de cruz até a extensão máxima de seu alcance. Após acertar, reduz a cura recebida pelo alvo.",
  str_guide_circle_N37ranger_RtT = "Características do inimigo",
  str_guide_circle_N37ranger_Lb = "Aproxime-se rapidamente e priorize eliminá-los.",
  str_guide_circle_N37ranger_LbT = "Tática de Abordagem",
  str_guide_circle_N37light_Lt = "Um membro enorme da gangue de força imensa, habilidoso em usar seus braços mecânicos para combate. Além disso, ele pode oferecer suporte a outras forças inimigas de Umbraton no campo de batalha.",
  str_guide_circle_N37light_LtT = "Especialista em Suporte de Gangue",
  str_guide_circle_N37light_Rt = "Fornece um aumento de ATK aos membros da Umbraton dentro de 1 cluster circundante; cura-se quando seu HP cai abaixo de uma certa porcentagem.",
  str_guide_circle_N37light_RtT = "Características do inimigo",
  str_guide_circle_N37light_Lb = "Elimine-os de uma só vez para evitar a auto-cura contínua deles.",
  str_guide_circle_N37light_LbT = "Tática de Abordagem",
  str_guide_circle_n37_trap2803501_RtT = "Casa Escura",
  str_guide_circle_n37_trap2803501_Rt = "A próxima peça nesta localização será garantidamente do mesmo elemento que a peça atual.",
  str_guide_circle_n37_trap2803501_RbT = "Tática de Abordagem",
  str_guide_circle_n37_trap2803501_Rb = "Use habilidades conversoras para converter os elementos das casas e maximizar seus efeitos.",
  str_guide_circle_N37cike_LtT = "Assassino de Gangue",
  str_guide_circle_N37cike_Lt = "Lança 2 golpes rápidos consecutivos contra o inimigo e rouba os atributos do alvo.",
  str_guide_circle_N37cike_Lb = "Derrote os inimigos o mais rápido possível. Não deixe que eles ataquem você continuamente.",
  str_guide_circle_N37cike_LbT = "Tática de Abordagem",
  str_guide_warn_551105 = "Toque aqui!",
  str_guide_warn_551106 = "O sistema de Iluminação foi ativado. Os atributos dos Aurorians agora podem ser aprimorados de forma abrangente. Toque para entrar no Módulo de Água.",
  str_guide_warn_551107 = "A lista à esquerda permite que você alterne rapidamente entre Módulos de diferentes Elementos.",
  str_guide_warn_551108 = "Veja o nível e progresso deste Módulo de Elemento aqui.",
  str_guide_warn_551109 = "Veja os detalhes da atualização do módulo aqui.",
  str_guide_warn_551110 = "Se tiver alguma dúvida, pode ver a descrição detalhada aqui.",
  str_guide_warn_19000101 = "Aqui, você pode resgatar tesouros, trazendo relíquias preciosas dos navios naufragados de volta à superfície, uma por uma.",
  str_guide_warn_19000102 = "As relíquias encontradas serão documentadas neste Arquivo de Relíquias. Abra-o para acessar os registros relacionados.",
  str_guide_warn_19000103 = "Se tiver alguma dúvida, fique à vontade para consultar as instruções de ajuda aqui para esclarecimentos.",
  str_guide_warn_19000104 = "Toque nas relíquias no campo para movê-las para a área de resgate abaixo.",
  str_guide_warn_19000105 = "Quando o número de relíquias idênticas na área de resgate chegar a 3, a relíquia será resgatada com sucesso e removida dos espaços.",
  str_guide_warn_19000106 = "Aqui, use a função de armazenamento de relíquias para mover relíquias dos espaços de resgate para o campo, evitando falhas porque todos os espaços estão preenchidos.",
  str_guide_cage_Rt = "Pode ser esmagado pelas Habilidades de Dano de Área dos Aurorianos. Novos inimigos podem aparecer depois que ele é esmagado!",
  str_guide_cage_RtT = "Armadilha Especial - Jaula",
  str_guide_circle_N38boss_Lt = "Uma arma perigosa criada pela combinação das características mortais de várias criações mecânicas, incluindo tecnologia da Astra. Fontes de energia comuns são incapazes de manter esta criatura gigante funcionando.",
  str_guide_circle_N38boss_LtT = "Stinger: Coalescência",
  str_guide_circle_N38boss_Rt = "Cada Besta Mecânica que compõe parte de seu corpo possui seu próprio ataque único. A cauda pode acumular Energia para causar dano garantido aos seus alvos, mas também é relativamente frágil.",
  str_guide_circle_N38boss_RtT = "Características do inimigo",
  str_guide_circle_N38boss_Lb = "Ataque a cauda dele com Aurorians Atiradores primeiro para torná-lo temporariamente incapaz de se mover, e então aproveite essa oportunidade para causar dano.",
  str_guide_circle_N38boss_LbT = "Tática de Abordagem",
  str_guide_warn_13800101 = "Etched Upon the Ocean Drifting Begonia I está disponível agora!\nHora de conhecer novos amigos e embarcar em uma nova aventura em The Homecoming!",
  str_guide_warn_13800102 = "Gaste Prismas em estágios da história principal e de Incursão: Recursos para obter Notas Promissórias da Guilda Lin.",
  str_guide_warn_13800103 = "Em Navio Perdido no Mar, enfrentaremos uma série de desafios mais complexos.",
  str_guide_warn_13800104 = "Nas Docas, use as Notas Promissórias da Guilda Lin para resgatar várias recompensas.",
  str_guide_warn_13800105 = "Lembre-se de entrar no jogo todos os dias para receber as recompensas de login do Berth.",
  str_guide_warn_13800106 = "Enfrente os estágios da história do evento e complete as missões em seu Livro de Eventos Especiais!",
  str_guide_warn_13800107 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  str_guide_crab_Rt = "Esta criação de ferramenta mecânica foi projetada para ajudar os artesãos a fazer invenções engenhosas. Mais tarde, foi modificada para que uma variação desta invenção pudesse armazenar Força de Chama em seu interior. Nunca foi destinada a ser usada como uma arma.",
  str_guide_crab_RtT = "Caranguejo Forjado em Fornalha",
  str_guide_crab_Lt = "Move lateralmente enquanto cospe chamas para atacar alvos à sua frente.",
  str_guide_crab_LtT = "Características do inimigo",
  str_guide_crab_Lb = "O Caranguejo Forjado em Fornalha tem um padrão de movimento fixo e não pode virar, então fique atrás dele antes de começar a causar dano.",
  str_guide_crab_LbT = "Tática de Abordagem",
  str_guide_warn_13900101 = "Sombras Abaixo da Escuridão já estão disponíveis!\nHora de conhecer novos amigos e embarcar em uma nova aventura em Sob as Sombras!",
  str_guide_warn_13900102 = "Gaste Prismas em estágios da história principal e de Incursão: Recursos para obter Tokens Cloudrover.",
  str_guide_warn_13900103 = "Em Deadly Arena, enfrentaremos uma série de desafios mais complexos.",
  str_guide_warn_13900104 = "No Dirigível Cloudrover, use Tokens Cloudrover para resgatar várias recompensas.",
  str_guide_warn_13900105 = "Lembre-se de entrar no jogo todos os dias para receber as recompensas de Visitante.",
  str_guide_warn_13900106 = "Enfrente os estágios da história do evento e complete as missões em seu Livro de Eventos Especiais!",
  str_guide_warn_13900107 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  str_guide_circle_S4boss_Lt = "Uma espada habilmente forjada a partir da engenhosidade do Reino Ye de Longzhou. Originalmente, foi concebida como uma arma de autodefesa para aqueles que não sabiam se defender com uma espada, mas agora se tornou uma espada maligna amaldiçoada após cair nas mãos de vilões.",
  str_guide_circle_S4boss_LtT = "Vilanor: Armadilha Amaldiçoada",
  str_guide_circle_S4boss_Rt = "Após se tornar Vilanor, suas habilidades são grandemente aprimoradas, ganhando o poder de se mover livremente pelo campo e gerar espadas a partir de energia maligna.",
  str_guide_circle_S4boss_RtT = "Características do inimigo",
  str_guide_circle_S4boss_Lb = "Vilanor tem a habilidade de abrir o espaço e criar Paredes Proibidas, então você pode usar Aurorianos que têm habilidades de teletransporte para pisar em Armadilhas de Exorcismo e atacar Vilanor facilmente após remover as Paredes Proibidas.",
  str_guide_circle_S4boss_LbT = "Tática de Abordagem",
  str_guide_warn_16021911 = "É necessário selecionar 1 aliado ou Peça Sombria para usar Istvan: Habilidade Ativa de Pith Marcado.",
  str_guide_warn_16021912 = "Aqui é onde você pode ver o número de Dádivas das Sombras usadas pelo aliado atual. Não pode ser lançado neste aliado se um número insuficiente tiver sido usado.",
  str_guide_warn_16021913 = "Lance a habilidade em Areia.",
  str_guide_warn_16021914 = "Nesta batalha, o custo desta habilidade aumenta +1 sempre que uma Habilidade Ativa é lançada neste aliado.",
  str_guide_warn_80040111 = "Navegador, olhe para cá! Você ganhou uma nova habilidade no Sonho!",
  str_guide_warn_80040112 = "Suas habilidades ficarão mais fortes à medida que você se aprofunda nos sonhos. Faça bom uso delas!",
  str_guide_circle_shenghuaboss_Lt = "Este super soldado é um Eclipsita que foi equipado com dispositivos mecânicos por todo o corpo para torná-lo mais resistente, mais feroz e mais intimidador.",
  str_guide_circle_shenghuaboss_LtT = "Super-Soldado Blaugm",
  str_guide_circle_shenghuaboss_Rt = "Um super soldado intimidador que se destaca em esmagar inimigos próximos com seus ataques.",
  str_guide_circle_shenghuaboss_RtT = "Características do inimigo",
  str_guide_circle_shenghuaboss_Lb = "Blaugm tem alta resistência ao dano de Ataque Normal, então tente causar dano com Combos ou Habilidades Ativas.",
  str_guide_circle_shenghuaboss_LbT = "Tática de Abordagem",
  str_guide_circle_ylxs_Lt = "Ulysses modificou seu corpo extensivamente para realizar seus ideais extremos. Ele não é mais um Aurorian agora.",
  str_guide_circle_ylxs_LtT = "Ulysses Bio",
  str_guide_circle_ylxs_Rt = "Ulysses usa diferentes estratégias de ataque com base nas habilidades dos Aurorianos.",
  str_guide_circle_ylxs_RtT = "Características do inimigo",
  str_guide_circle_ylxs_Lb = "Com base na condição atual da equipe, ataque com sabedoria e evite receber dano de Ulysses para aumentar grandemente a chance de vitória.",
  str_guide_circle_ylxs_LbT = "Tática de Abordagem",
  str_guide_warn_shzyx_01 = "Aviso! O Protótipo Guardião foi ativado.",
  str_guide_warn_shzyx_02 = "Esta máquina antiga construída pelo Engenheiro parece ter autoconsciência.",
  str_guide_warn_shzyx_03 = "Restringe os Ataques Normais, Habilidades Ativas ou Combos em Cadeia dos Aurorianos. Também danifica inimigos e protege aliados ao mesmo tempo.",
  str_guide_warn_shzyx_04 = "Com base na condição atual da equipe, ataque com sabedoria para ter uma chance de enfrentá-lo. Não o subestime!",
  str_guide_circle_soilder1_Rt = "Uma arma de guerra criada através da fusão de Eclipsitas e Aurorians. As características dos Aurorians foram mantidas o máximo possível, e a mecanização não é muito óbvia, mas ainda é muito perigosa.",
  str_guide_circle_soilder1_RtT = "Soldado Voidcross",
  str_guide_circle_soilder1_Rb = "Uma forma de vida mecânica que ataca hackeando e cortando.",
  str_guide_circle_soilder1_RbT = "Características do inimigo",
  str_guide_circle_soilder1_Lb = "O Soldado Voidcross pode refletir o dano do Ataque Normal dos Aurorians. Mantenha distância e tente causar dano com Combos ou Habilidades Ativas.",
  str_guide_circle_soilder1_LbT = "Tática de Abordagem",
  str_guide_circle_soilder2_Rt = "Uma arma de guerra criada através da fusão de Eclipsitas e Aurorians. É protegida por uma espessa camada de armadura mecânica, e sua força foi aprimorada ao máximo possível.",
  str_guide_circle_soilder2_RtT = "Soldado Ululat",
  str_guide_circle_soilder2_Rb = "O poder e a defesa desta forma de vida mecânica modificada foram muito melhorados, e ela é excelente em atacar com explosões e outros métodos semelhantes.",
  str_guide_circle_soilder2_RbT = "Características do inimigo",
  str_guide_circle_soilder2_Lb = "O Soldado Ululat pode refletir o dano do Ataque Normal dos Aurorians. Preste atenção no alcance do ataque e tente causar dano com Combos em Cadeia ou Habilidades Ativas.",
  str_guide_circle_soilder2_LbT = "Tática de Abordagem",
  str_guide_circle_soilder3_Rt = "Uma super arma criada através da fusão de Eclipsitas e Aurorians. Ela não possui mais características Aurorianas e agora é uma existência totalmente mecânica.",
  str_guide_circle_soilder3_RtT = "Super-Soldado Meaugm",
  str_guide_circle_soilder3_Rb = "Esta forma de vida mecânica modificada pode usar sua armadura espessa como uma arma, tornando-a muito difícil de lidar.",
  str_guide_circle_soilder3_RbT = "Características do inimigo",
  str_guide_circle_soilder3_Lb = "O Super-Soldado Meaugm pode refletir o dano do Ataque Normal dos Aurorianos e restaurar seu próprio HP, então tente terminar a batalha o mais rápido possível.",
  str_guide_circle_soilder3_LbT = "Tática de Abordagem",
  str_guide_warn_14000101 = "Através da Névoa, Ecos do Passado estão agora disponíveis!\nVamos começar uma nova história na Parte 2!",
  str_guide_warn_14000102 = "Os capítulos da história que são desbloqueados neste evento, bem como os capítulos que foram explorados até agora, são exibidos aqui.",
  str_guide_warn_14000103 = "Toque em Explorar Agora para ir diretamente ao mapa de exploração. Gaste Prismas em estágios da história principal e estágios de Incursão: Recursos para obter Penas de Caelestite.",
  str_guide_warn_14000104 = "Na Aurora Exchange, use Penas de Caelestite para resgatar várias recompensas.",
  str_guide_warn_14000105 = "Enfrente os estágios da história do evento e complete as missões em seu Livro de Eventos Especiais!",
  str_guide_warn_14000106 = "Lembre-se de entrar no jogo todos os dias para receber as recompensas de login do Navigation.",
  str_guide_warn_14000107 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  str_guide_warn_14100101 = "Drifting Begonia II: Chegou o Dragão, Espíritos Desaparecem está agora disponível! Hora de conhecer novos amigos e embarcar em uma nova aventura na Dança do Dragão!",
  str_guide_warn_14100102 = "Gaste Prismas em estágios da história principal e estágios de Incursão: Recursos para obter Incenso de Oração.",
  str_guide_warn_14100103 = "Em Absconding Evil, enfrentaremos uma série de desafios mais complexos.",
  str_guide_warn_14100104 = "Em Bênçãos do Mar, use Incenso de Oração para resgatar várias recompensas.",
  str_guide_warn_14100105 = "Lembre-se de entrar no jogo todos os dias para receber as recompensas de Visitante.",
  str_guide_warn_14100106 = "Enfrente os estágios da história do evento e complete as missões em seu Livro de Eventos Especiais!",
  str_guide_warn_14100107 = "Se você tiver alguma dúvida sobre o evento, pode ver a descrição detalhada aqui.",
  str_guide_circle_yingzi_LtT = "Vontade Malévola: Sombra",
  str_guide_circle_yingzi_Lt = "Manchado pela Vontade Maligna, seus poderes de invocação mudaram sutilemente.",
  str_guide_circle_yingzi_RtT = "Características do inimigo",
  str_guide_circle_yingzi_Rt = "O número de runas invocadas cada vez aumenta significativamente.",
  str_guide_circle_miran_LtT = "Vontade Malévola: Murkmite",
  str_guide_circle_miran_Lt = "Manchado pela Vontade Malévola, seus ataques mudaram sutilemente.",
  str_guide_circle_miran_RtT = "Características do inimigo",
  str_guide_circle_miran_Rt = "Ao acertar, seu ataque reduz imediatamente o Ponto de Força do jogador em 2.",
  str_guide_circle_aogeyang_LtT = "Vontade Malévola: Augean",
  str_guide_circle_aogeyang_Lt = "Manchado pela Vontade Maligna, sua habilidade mudou sutilemente.",
  str_guide_circle_aogeyang_RtT = "Características do inimigo",
  str_guide_circle_aogeyang_Rt = "Ganha um aumento significativo na mobilidade e, a cada 2 rodadas, invoca monstros para a área próxima para atacar o jogador em conjunto.",
  str_guide_circle_jingmianta_LtT = "Torre Refletora: Vitalizada",
  str_guide_circle_jingmianta_Lt = "Dispositivo espelho que se transforma em ambientes especiais, oferecendo assistência às equipes Aurorianas.",
  str_guide_circle_jingmianta_RtT = "Características da armadilha",
  str_guide_circle_jingmianta_Rt = "Posicionar-se no campo fornece energia especial para a equipe, recuperação de Ponto de Força por rodada +1.",
  str_guide_circle_laolong_LtT = "Vontade Malévola: Gaiola",
  str_guide_circle_laolong_Lt = "Dentro da gaiola estão inimigos presos por razões específicas. Uma vez libertados, eles podem ajudar o Chefe ou expor a vulnerabilidade do Chefe.",
  str_guide_circle_laolong_RtT = "Características da armadilha",
  str_guide_circle_laolong_Rt = "Toque na armadilha e gaste 3 Pontos de Força para libertar os inimigos da jaula. Embora eles não te ajudem na batalha, o dano que eles recebem será parcialmente transferido para o Chefe.",
  str_guide_circle_paotai_LtT = "Torreta Ágil",
  str_guide_circle_paotai_Lt = "Uma torreta de alto desempenho. Embora requeira operação manual, é potencialmente mais eficaz do que as automáticas.",
  str_guide_circle_paotai_RtT = "Características da armadilha",
  str_guide_circle_paotai_Rt = "Toque na armadilha e gaste 2 Pontos de Força para lançar 1 ataque, infligindo dano e debuffs nos inimigos em uma linha reta à frente.",
  str_guide_circle_fengchuan_RtT = "Características da armadilha",
  str_guide_circle_fengchuan_Rt = "Torna-se ainda mais portátil e fácil de usar, capaz de liberar habilidades consumindo os Pontos de Força da equipe.",
  str_guide_circle_8024001 = "Em Purificando o Mal na Noite Silenciosa, a equipe não se move mais de acordo com as regras originais, mas consome Pontos de Força para o movimento.",
  str_guide_circle_8024002 = "Os Pontos de Força atuais do jogador são exibidos à esquerda, onde pré-visualizações em tempo real dos Pontos de Força restantes estão disponíveis durante as conexões de ladrilhos.",
  str_guide_circle_8024003 = "O movimento anterior parece ter esgotado seus Pontos de Força. Mas não se preocupe; você receberá uma certa quantidade de Pontos de Força no início de cada rodada, e a reposição da próxima rodada será exibida no canto direito.",
  str_guide_circle_8024004 = "Toque aqui para ver os efeitos de talento atualmente ativos.",
  str_guide_circle_8024005 = "Os Pontos de Força não consumidos em cada rodada não desaparecerão no final da rodada. Às vezes, pode ser uma escolha sábia economizar os Pontos de Força de uma rodada.",
  str_guide_season_talent_tree_1 = "A Seleção de Talentos é composta por vários Nós de Formação e Talentos e concede bônus adicionais. Vamos começar ativando o primeiro Nó de Formação!",
  str_guide_season_talent_tree_2 = "Toque em Ativar para consumir Energia Auspiciosa e ativar o primeiro Nodo de Formação.",
  str_guide_season_talent_tree_3 = "Uma vez que um Nó de Formação é ativado, seus efeitos começarão a ter efeito nas batalhas. Também é possível desbloquear slots de Truque em alguns Nós de Formação.",
  str_guide_season_talent_tree_4 = "Agora vamos tentar ativar e equipar a primeira Habilidade Passiva. Por favor, toque nesta Habilidade Passiva.",
  str_guide_season_talent_tree_5 = "Toque em Ativar para consumir Energia Auspiciosa e ativar este Dom.",
  str_guide_season_talent_tree_6 = "Após ativar o Truque, arraste-o para o slot de Truque correspondente para equipá-lo e usar seu efeito na batalha.",
  str_guide_season_talent_tree_7 = "Os slots de habilidade têm certas restrições de tipo de habilidade. O primeiro slot de habilidade só pode ser equipado com uma Habilidade Caelestite, e outros slots só podem ser equipados com Habilidades Passivas.",
  str_guide_season_talent_tree_8 = "Por favor, veja as informações de jogabilidade para mais detalhes sobre as regras.",
  str_guide_season_trade_out_1 = "Daytime Merchant é uma nova jogabilidade na qual os Navegadores podem gerenciar um porto e navios para ganhar Capital de Trabalho e Energia Auspiciosa.",
  str_guide_season_trade_out_2 = "Purgar o Mal na Noite Silenciosa é uma nova jogabilidade com estágios lineares. Nesta jogabilidade, os Navegadores se moverão de acordo com um novo sistema e usarão Truques de Feng Shui para obter vantagens na batalha!",
  str_guide_season_trade_in_1 = "Os navegadores precisarão gerenciar portos e navios e podem tocar em Atualização de Renovação no canto superior direito para atualizar o alvo selecionado.",
  str_guide_season_trade_in_2 = "Os níveis do porto e do navio afetarão a velocidade de descarga do porto, a carga restante dos navios e o tempo necessário para descarregar as mercadorias após a conclusão das viagens.",
  str_guide_season_trade_in_3 = "Membros da tripulação contratados podem ser designados para vários navios, mas cada membro da tripulação só pode ser designado para um navio de cada vez.",
  str_guide_season_trade_in_4 = "Os membros da tripulação possuem atributos de Expedição, Capacidade de Envio e Prontidão. Melhore os portos para contratar membros da tripulação mais capazes.",
  str_guide_season_trade_in_5 = "O Status do Navio de cada embarcação é determinado pelos Pontos de Habilidade dos membros da tripulação designados para o navio. Se um navio não atender aos requisitos de nível do navio, seu Status do Navio será significativamente menor, o que afetará seu lucro.",
