  str_guide_season_trade_in_8 = "Por favor, veja as informações de jogabilidade para mais detalhes sobre as regras.",
  str_guide_mouse_Rt = "Fiendlings onívoros de pequeno porte com cultivo insuficiente, mantendo uma natureza selvagem. Eles sempre se infiltram em moradias aurorianas para roubar comida. Alguns mais agressivos podem até causar danos.",
  str_guide_mouse_RtT = "Demônio: Rato",
