  str_guide_circle_2909301_LbT = "Características do inimigo",
  str_guide_circle_80050001_Rt = "Ganha 10 pontos de Energia de Combate no início de cada rodada. Concede aumento de ATK a todos os monstros no campo se houver mais de 30 pontos de energia no final da rodada.",
  str_guide_circle_80050001_RtT = "Eclipsita com info - Correio",
