  str_guide_circle_2921201_RtT = "Características do inimigo",
  str_guide_circle_2921201_Lb = "Certifique-se de não ser atingido por habilidades especiais; o resto depende de suas capacidades.",
  str_guide_circle_2921201_LbT = "Tática de Abordagem",
